// Wygenerowane przez build-files.js, nie edytować ręcznie
// data/W01.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W01-01", w: "W01", c: "dm-def", type: "single", q: "Automatyczne lub półautomatyczne wydobywanie ukrytych, zrozumiałych i użytecznych wzorców z danych to robocza definicja:", options: ["hurtowni danych", "analizy OLAP", "data mining", "metodyki CRISP-DM"], correct: [2], explain: "To definicja robocza data mining ze slajdu o procesie KDD.", src: "W01, slajd 4", note: "W01-wstep" },
  { id: "W01-02", w: "W01", c: "dm-def", type: "single", q: "Które stwierdzenie o data mining jest zgodne z wykładem?", options: ["To synonim całego projektu odkrywania wiedzy", "To etap procesu KDD, w którym są algorytmy", "To ostatni etap metodyki CRISP-DM", "To raportowanie tego, co już się stało"], correct: [1], explain: "Eksploracja danych jest etapem odkrywania wiedzy (KDD), a nie synonimem całego projektu.", src: "W01, slajd 4", note: "W01-wstep" },
  { id: "W01-03", w: "W01", c: "kdd-etapy", type: "single", q: "Który etap procesu KDD następuje bezpośrednio przed data mining?", options: ["czyszczenie i integracja", "wybór danych", "interpretacja i wdrożenie", "transformacja cech"], correct: [3], explain: "Kolejność KDD: wybór danych, czyszczenie i integracja, transformacja cech, data mining, interpretacja i wdrożenie.", src: "W01, slajd 4", note: "W01-wstep" },
  { id: "W01-04", w: "W01", c: "kdd-etapy", type: "single", q: "Czym jest KDD według słownika pojęć z wykładu?", options: ["Pełnym procesem odkrywania wiedzy z danych", "Iteracyjną metodyką prowadzenia projektu", "Formalną reprezentacją zależności z danych", "Wydobywaniem wzorców i modeli z danych"], correct: [0], explain: "KDD to pełny proces odkrywania wiedzy z danych; data mining jest jego etapem.", src: "W01, slajd 16", note: "W01-wstep" },
  { id: "W01-05", w: "W01", c: "crisp-dm", type: "single", q: "Iteracyjna metodyka prowadzenia projektu data mining to:", options: ["Proces KDD", "Analiza OLAP", "CRISP-DM", "Hurtownia danych"], correct: [2], explain: "Słownik: CRISP-DM to iteracyjna metodyka prowadzenia projektu data mining.", src: "W01, slajd 16", note: "W01-wstep" },
  { id: "W01-06", w: "W01", c: "crisp-dm", type: "single", q: "Który etap CRISP-DM następuje po etapie „Ocena”?", options: ["Modelowanie", "Wdrożenie", "Zrozumienie danych", "Przygotowanie danych"], correct: [1], explain: "Etap 5 to Ocena, etap 6 to Wdrożenie; model nie jest końcem projektu.", src: "W01, slajd 5", note: "W01-wstep" },
  { id: "W01-07", w: "W01", c: "crisp-dm", type: "single", q: "Model daje słaby wynik. Co według wykładu często trzeba zrobić?", options: ["Wyłącznie zmienić algorytm na inny", "Zakończyć projekt na etapie oceny", "Wrócić do definicji celu, danych albo cech", "Od razu wdrożyć model i go monitorować"], correct: [2], explain: "Proces CRISP-DM jest iteracyjny: słaby wynik często oznacza powrót do celu, danych lub cech.", src: "W01, slajd 5", note: "W01-wstep" },
  { id: "W01-08", w: "W01", c: "typy-zadan", type: "single", q: "Które zadanie odpowiada na pytanie „Jaka wartość?” (np. sprzedaż za tydzień)?", options: ["Klasyfikacja", "Klasteryzacja", "Redukcja wymiaru", "Predykcja"], correct: [3], explain: "Predykcja szacuje wartość; klasyfikacja przypisuje klasę.", src: "W01, slajd 6", note: "W01-wstep" },
  { id: "W01-09", w: "W01", c: "typy-zadan", type: "single", q: "Firma chce wyodrębnić segmenty klientów bez znanych z góry klas. Jaki to typ zadania?", options: ["Klasteryzacja", "Klasyfikacja", "Reguły asocjacyjne", "Predykcja"], correct: [0], explain: "Klasteryzacja odpowiada na pytanie „Jakie grupy?”, przykład: segmenty klientów.", src: "W01, slajd 6", note: "W01-wstep" },
  { id: "W01-10", w: "W01", c: "typy-zadan", type: "single", q: "Na jakie pytanie odpowiadają reguły asocjacyjne?", options: ["Co jest nietypowe?", "Co współwystępuje?", "Jak uprościć opis?", "Jaka klasa?"], correct: [1], explain: "Reguły asocjacyjne szukają współwystępowania, np. produktów kupowanych razem.", src: "W01, slajd 6", note: "W01-wstep" },
  { id: "W01-11", w: "W01", c: "zastosowania", type: "single", q: "Do jakiego zadania przypisano na wykładzie wykrywanie nadużyć (alert do weryfikacji)?", options: ["Reguły asocjacyjne", "Predykcja / redukcja wymiaru", "Anomalie / klasyfikacja", "Klasteryzacja / predykcja"], correct: [2], explain: "Nadużycia: zachowanie transakcji, alert do weryfikacji, zadanie anomalie / klasyfikacja.", src: "W01, slajd 7", note: "W01-wstep" },
  { id: "W01-12", w: "W01", c: "zastosowania", type: "single", q: "Przykład „Koszyk” (paragony / sesje → rekomendacje i ekspozycja) to zadanie:", options: ["Redukcja wymiaru", "Reguły asocjacyjne", "Anomalie / klasyfikacja", "Klasteryzacja"], correct: [1], explain: "Koszyk zakupowy to klasyczny przykład reguł asocjacyjnych.", src: "W01, slajd 7", note: "W01-wstep" },
  { id: "W01-13", w: "W01", c: "elementy-zadania", type: "single", q: "Który element definicji zadania odpowiada na pytanie „co wiadomo w chwili decyzji?”", options: ["Etykieta", "Horyzont", "Jednostka", "Cechy"], correct: [3], explain: "Cechy to to, co wiadomo w chwili decyzji; horyzont mówi, kiedy ma wystąpić zdarzenie.", src: "W01, slajd 8", note: "W01-wstep" },
  { id: "W01-14", w: "W01", c: "elementy-zadania", type: "single", q: "W zadaniu „przewidzieć klientów, którzy w ciągu 30 dni wypowiedzą umowę” fraza „w ciągu 30 dni” to:", options: ["horyzont", "jednostka", "koszt błędu", "etykieta"], correct: [0], explain: "Horyzont określa, kiedy ma wystąpić przewidywane zdarzenie.", src: "W01, slajd 8", note: "W01-wstep" },
  { id: "W01-15", w: "W01", c: "bi-vs-dm", type: "single", q: "Które pytanie wykład przypisuje do data mining, a nie do BI / OLAP?", options: ["Ile sprzedaliśmy?", "Który region spadł?", "Co może się stać?", "Co się stało?"], correct: [2], explain: "BI / OLAP pyta, co się stało; data mining szuka wzorców i prognoz.", src: "W01, slajd 9", note: "W01-wstep" },
  { id: "W01-16", w: "W01", c: "bi-vs-dm", type: "single", q: "Co według wykładu charakteryzuje hurtownię danych?", options: ["Szukanie wzorców i prognoz", "Spójne dane historyczne", "Odpowiedź „co może się stać?”", "Wykrywanie nietypowych transakcji"], correct: [1], explain: "Hurtownia: spójne dane historyczne, modele faktów i wymiarów, źródło dla analiz.", src: "W01, slajd 9", note: "W01-wstep" },
  { id: "W01-17", w: "W01", c: "przeuczenie", type: "single", q: "Model świetnie pasuje do danych treningowych, ale słabo działa na nowych danych. To:", options: ["niedouczenie", "dryf danych", "przeciek danych", "przeuczenie"], correct: [3], explain: "Przeuczenie: model nauczył się szczegółów przeszłości zamiast uogólniać.", src: "W01, slajd 10", note: "W01-wstep" },
  { id: "W01-18", w: "W01", c: "przeuczenie", type: "single", q: "Czym jest niedouczenie?", options: ["Model jest za prosty i pomija ważne zależności", "Model pasuje do treningu, a słabo do nowych danych", "Model oceniany na danych spoza uczenia", "Model używa informacji z przyszłości"], correct: [0], explain: "Niedouczenie: model zbyt prosty, nie wychwytuje ważnych zależności.", src: "W01, slajd 10", note: "W01-wstep" },
  { id: "W01-19", w: "W01", c: "metryki", type: "single", q: "Która metryka odpowiada na pytanie „ile alarmów było trafnych?”", options: ["Accuracy", "Recall", "Precision", "Koszt błędu"], correct: [2], explain: "Precision: ile alarmów było trafnych; recall: ile przypadków wykryliśmy.", src: "W01, slajd 11", note: "W01-wstep" },
  { id: "W01-20", w: "W01", c: "metryki", type: "single", q: "W przykładzie medycznym z wykładu false negative oznacza:", options: ["zdrowego skierowanego na badania", "chorego uznanego za zdrowego", "chorego uznanego za chorego", "zdrowego uznanego za zdrowego"], correct: [1], explain: "FN to chory uznany za zdrowego; FP to zdrowy skierowany na dalsze badania.", src: "W01, slajd 11", note: "W01-wstep" },
  { id: "W01-21", w: "W01", c: "przeciek", type: "single", q: "Czym jest przeciek danych według słownika pojęć?", options: ["Zmianą relacji po wdrożeniu modelu", "Uproszczoną lub błędną definicją celu", "Próbą niepodobną do populacji", "Użyciem informacji niedostępnej przy predykcji"], correct: [3], explain: "Przeciek danych to użycie informacji niedostępnej w chwili predykcji (np. z przyszłości lub z etykiety).", src: "W01, slajd 16", note: "W01-wstep" },
  { id: "W01-22", w: "W01", c: "przeciek", type: "single", q: "Po wdrożeniu modelu relacje w danych się zmieniają i model traci jakość. Którą pułapkę opisano?", options: ["Przeciek danych", "Dryf danych", "Zła etykieta", "Niereprezentatywna próba"], correct: [1], explain: "Dryf danych: relacje zmieniają się po wdrożeniu.", src: "W01, slajd 12", note: "W01-wstep" },
  { id: "W01-23", w: "W01", c: "pulapki", type: "multi", q: "Które z poniższych wykład wymienia jako typowe pułapki w projektach data mining?", options: ["Niereprezentatywna próba", "Korelacja ≠ przyczynowość", "Granice automatyzacji", "Brak interpretacji"], correct: [0, 1, 3], explain: "Pułapki: przeciek danych, zła etykieta, niereprezentatywna próba, korelacja ≠ przyczynowość, dryf danych, brak interpretacji.", src: "W01, slajd 12", note: "W01-wstep" },
  { id: "W01-26", w: "W01", c: "pulapki", type: "single", q: "Model uczy się uproszczonej lub błędnej definicji celu. Którą pułapkę opisano?", options: ["Brak interpretacji", "Zła etykieta", "Niereprezentatywna próba", "Korelacja ≠ przyczynowość"], correct: [1], explain: "Zła etykieta: model uczy się uproszczonej lub błędnej definicji celu.", src: "W01, slajd 12", note: "W01-wstep" },
  { id: "W01-27", w: "W01", c: "pulapki", type: "single", q: "Co według wykładu oznacza pułapka „Korelacja ≠ przyczynowość”?", options: ["Trening nie przypomina populacji zastosowania", "Wynik nie jest zrozumiały dla decydentów", "Wzorzec nie musi oznaczać przyczyny", "Relacje zmieniają się po wdrożeniu"], correct: [2], explain: "Korelacja ≠ przyczynowość: wykryty wzorzec nie musi oznaczać przyczyny.", src: "W01, slajd 12", note: "W01-wstep" },
  { id: "W01-24", w: "W01", c: "odpowiedzialna", type: "single", q: "Który obszar odpowiedzialnej eksploracji danych mówi, że historyczne dane mogą przenosić nierówności?", options: ["Prywatność", "Wyjaśnialność", "Kontrola", "Stronniczość"], correct: [3], explain: "Stronniczość: historyczne dane mogą przenosić nierówności.", src: "W01, slajd 13", note: "W01-wstep" },
  { id: "W01-28", w: "W01", c: "odpowiedzialna", type: "single", q: "Co według wykładu obejmuje obszar „Kontrola” w odpowiedzialnej eksploracji danych?", options: ["Minimalizację danych, cel przetwarzania i dostęp", "Wersjonowanie, monitoring i możliwość odwołania", "Rozumienie wyniku przez użytkownika i decydenta", "Ograniczenie decyzji całkowicie automatycznych"], correct: [1], explain: "Kontrola: wersjonowanie danych i modeli, monitoring, możliwość odwołania.", src: "W01, slajd 13", note: "W01-wstep" },
  { id: "W01-29", w: "W01", c: "odpowiedzialna", type: "single", q: "Firma zbiera tylko dane potrzebne do celu przetwarzania i ogranicza do nich dostęp. Którego obszaru odpowiedzialnej eksploracji to dotyczy?", options: ["Kontrola", "Wyjaśnialność", "Prywatność", "Stronniczość"], correct: [2], explain: "Prywatność: minimalizacja danych, cel przetwarzania, dostęp.", src: "W01, slajd 13", note: "W01-wstep" },
  { id: "W01-25", w: "W01", c: "pojecia", type: "single", q: "Czym jest cecha według słownika pojęć?", options: ["Wartością przewidywaną w uczeniu", "Zmienną opisującą obiekt", "Reprezentacją zależności z danych", "Wzorcem ukrytym w danych"], correct: [1], explain: "Cecha to zmienna opisująca obiekt; etykieta to wartość przewidywana w uczeniu nadzorowanym.", src: "W01, slajd 16", note: "W01-wstep" },
  { id: "W01-30", w: "W01", c: "pojecia", type: "single", q: "Czym według słownika pojęć cecha różni się od etykiety?", options: ["Etykieta opisuje obiekt, a cechę się przewiduje", "Cecha opisuje obiekt, a etykietę się przewiduje", "Cecha jest znana dopiero po decyzji, etykieta przed nią", "Cecha to reprezentacja zależności wyuczona z danych"], correct: [1], explain: "Cecha to zmienna opisująca obiekt; etykieta to wartość przewidywana w uczeniu nadzorowanym.", src: "W01, slajd 16", note: "W01-wstep" },
  { id: "W01-31", w: "W01", c: "pojecia", type: "single", q: "Formalna reprezentacja zależności wyuczona z danych to według słownika pojęć:", options: ["etykieta", "data mining", "model", "cecha"], correct: [2], explain: "Słownik: model to formalna reprezentacja zależności wyuczona z danych.", src: "W01, slajd 16", note: "W01-wstep" },
]});

// data/W02.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W02-01", w: "W02", c: "gigo", type: "single", q: "Co według wykładu wyraża zasada „garbage in, garbage out”?", options: ["Jakość modelu zależy od jakości danych", "Algorytm ważniejszy jest niż cechy", "Błędne rekordy trzeba zawsze usuwać", "Więcej danych zawsze daje lepszy model"], correct: [0], explain: "Model uczy się wzorców obecnych w danych, także błędnych, więc jakość danych wyznacza jakość modelu.", src: "W02, slajd 2", note: "W02-przygotowanie-danych" },
  { id: "W02-26", w: "W02", c: "gigo", type: "single", q: "Model wykrył „zależność”, która okazała się skutkiem błędów w danych. Którą zasadę z wykładu ilustruje ta sytuacja?", options: ["„Garbage in, garbage out”", "Imputer dopasowuje się na treningu", "Cecha musi być dostępna w predykcji", "Outlierów nie usuwa się automatycznie"], correct: [0], explain: "Model uczy się wzorców z danych, także błędnych, więc błędy danych mogą być mylone z realnymi zależnościami.", src: "W02, slajd 2", note: "W02-przygotowanie-danych" },
  { id: "W02-02", w: "W02", c: "rodzaje-danych", type: "single", q: "Zmienna o wartościach „niski–średni–wysoki” to według wykładu dane:", options: ["nominalne", "binarne", "porządkowe", "liczbowe"], correct: [2], explain: "Dane porządkowe mają naturalną kolejność; nominalne (region, marka) jej nie mają.", src: "W02, slajd 5", note: "W02-przygotowanie-danych" },
  { id: "W02-27", w: "W02", c: "rodzaje-danych", type: "single", q: "Region, marka i typ klienta to według wykładu przykłady danych:", options: ["porządkowych", "nominalnych", "tekstowych", "binarnych"], correct: [1], explain: "Dane nominalne nie mają naturalnej kolejności; porządkowe to np. niski–średni–wysoki.", src: "W02, slajd 5", note: "W02-przygotowanie-danych" },
  { id: "W02-28", w: "W02", c: "rodzaje-danych", type: "single", q: "Które przyporządkowanie typu danych do przykładów jest NIEZGODNE z wykładem?", options: ["Binarne: tak/nie, 0/1", "Czasowe: data, godzina, sekwencja", "Porządkowe: kwota, temperatura", "Tekstowe: opis, komentarz"], correct: [2], explain: "Wiek, kwota i temperatura to dane liczbowe; porządkowe mają kolejność, np. niski–średni–wysoki.", src: "W02, slajd 5", note: "W02-przygotowanie-danych" },
  { id: "W02-03", w: "W02", c: "jakosc-wymiary", type: "single", q: "Który wymiar jakości danych odpowiada na pytanie „czy zapis jest jednolity między źródłami?”", options: ["Kompletność", "Spójność", "Poprawność", "Unikalność"], correct: [1], explain: "Spójność to jednolity zapis między źródłami; unikalność dotyczy zdublowanych rekordów.", src: "W02, slajd 6", note: "W02-przygotowanie-danych" },
  { id: "W02-04", w: "W02", c: "jakosc-wymiary", type: "single", q: "Audyt wykazał, że w zbiorze ten sam klient występuje w dwóch identycznych rekordach. Który wymiar jakości jest naruszony?", options: ["Aktualność", "Kompletność", "Poprawność", "Unikalność"], correct: [3], explain: "Unikalność: czy rekordy nie są zdublowane.", src: "W02, slajd 6", note: "W02-przygotowanie-danych" },
  { id: "W02-05", w: "W02", c: "brak-rodzaje", type: "single", q: "Czym według wykładu „zero” różni się od wartości brakującej?", options: ["Zero to pole bez sensu dla przypadku", "Zero to znana wartość liczbowa równa 0", "Zero to błąd pomiaru lub awaria", "Zero to odmowa odpowiedzi respondenta"], correct: [1], explain: "Wartość brakująca to brak wiedzy o odpowiedzi, a zero to znana wartość równa 0.", src: "W02, slajd 11", note: "W02-przygotowanie-danych" },
  { id: "W02-29", w: "W02", c: "brak-rodzaje", type: "single", q: "Pole nie ma sensu dla danego przypadku. Jak wykład nazywa taką sytuację?", options: ["Wartość brakująca", "Nie dotyczy", "Odmowa odpowiedzi", "Błąd pomiaru"], correct: [1], explain: "„Nie dotyczy” to pole bez sensu dla przypadku; wartość brakująca oznacza, że nie znamy odpowiedzi.", src: "W02, slajd 11", note: "W02-przygotowanie-danych" },
  { id: "W02-30", w: "W02", c: "brak-rodzaje", type: "single", q: "O której sytuacji wykład mówi, że brak może sam nieść sygnał?", options: ["O zerze jako znanej wartości", "O odmowie odpowiedzi", "O polu typu „nie dotyczy”", "O awarii zapisu danych"], correct: [1], explain: "Według slajdu odmowa odpowiedzi to brak, który może sam nieść sygnał.", src: "W02, slajd 11", note: "W02-przygotowanie-danych" },
  { id: "W02-06", w: "W02", c: "mcar-mar-mnar", type: "single", q: "Dochód częściej ukrywają osoby o wysokich dochodach. Jaki to mechanizm braków danych?", options: ["MCAR", "MAR", "MNAR", "brak typu „nie dotyczy”"], correct: [2], explain: "MNAR: brak zależy od nieobserwowanej wartości, czyli od samego dochodu.", src: "W02, slajd 12", note: "W02-przygotowanie-danych" },
  { id: "W02-07", w: "W02", c: "mcar-mar-mnar", type: "single", q: "Mechanizm MAR oznacza, że brak danych:", options: ["jest całkowicie losowy", "zależy od obserwowanych cech", "zależy od nieobserwowanej wartości", "wynika z odmowy odpowiedzi"], correct: [1], explain: "MAR: brak zależy od obserwowanych cech, np. występuje częściej w wybranym regionie.", src: "W02, slajd 12", note: "W02-przygotowanie-danych" },
  { id: "W02-08", w: "W02", c: "mcar-mar-mnar", type: "single", q: "Losowa awaria zapisu formularza powoduje braki. Jaki to mechanizm?", options: ["MAR", "MNAR", "MCAR", "błąd domenowy"], correct: [2], explain: "MCAR: brak całkowicie losowy, przykład ze slajdu to losowa awaria zapisu formularza.", src: "W02, slajd 12", note: "W02-przygotowanie-danych" },
  { id: "W02-09", w: "W02", c: "usuwanie", type: "single", q: "Kiedy według wykładu usunięcie kolumny ma sens?", options: ["Gdy braków jest niewiele i są całkowicie losowe", "Gdy braki dotyczą ważnej grupy klientów firmy", "Gdy braki w tej kolumnie mają wyraźny wzorzec", "Gdy braków jest bardzo dużo, a informacji mało"], correct: [3], explain: "Kolumnę usuwa się przy bardzo dużej liczbie braków i niskiej wartości informacyjnej; braki ze wzorcem czynią usuwanie ryzykownym.", src: "W02, slajd 13", note: "W02-przygotowanie-danych" },
  { id: "W02-31", w: "W02", c: "usuwanie", type: "single", q: "Kiedy według wykładu usuwanie danych z brakami jest ryzykowne?", options: ["Gdy braków jest mało i są losowe", "Gdy braki mają wyraźny wzorzec", "Gdy kolumna ma dużo braków i mało informacji", "Gdy braki wynikają z losowej awarii"], correct: [1], explain: "Usuwanie jest ryzykowne, gdy braki mają wzorzec lub dotyczą ważnej grupy; przy nielicznych losowych brakach jest możliwe.", src: "W02, slajd 13", note: "W02-przygotowanie-danych" },
  { id: "W02-32", w: "W02", c: "usuwanie", type: "single", q: "Które stwierdzenie o usuwaniu danych jest NIEZGODNE z wykładem?", options: ["Jest możliwe przy małej liczbie losowych braków", "Każde usunięcie zmienia próbę", "Jest bezpieczne, gdy braki mają wzorzec", "Może wprowadzać obciążenie do próby"], correct: [2], explain: "Według slajdu usuwanie jest ryzykowne, gdy braki mają wzorzec lub dotyczą ważnej grupy.", src: "W02, slajd 13", note: "W02-przygotowanie-danych" },
  { id: "W02-10", w: "W02", c: "imputacja-prosta", type: "single", q: "Którą prostą metodę imputacji wykład opisuje jako odporną i często dobrą dla rozkładów skośnych?", options: ["Średnią", "Medianę", "Modę", "Stałą „brak”"], correct: [1], explain: "Mediana jest odporna; średnia jest szybka, ale wrażliwa na wartości odstające.", src: "W02, slajd 14", note: "W02-przygotowanie-danych" },
  { id: "W02-11", w: "W02", c: "imputacja-prosta", type: "single", q: "Brakuje wartości w zmiennej nominalnej „marka”. Którą prostą imputację wskazuje wykład?", options: ["Medianę", "Średnią", "Modę", "Regresję"], correct: [2], explain: "Moda to najczęstsza kategoria, stosowana dla zmiennych nominalnych.", src: "W02, slajd 14", note: "W02-przygotowanie-danych" },
  { id: "W02-12", w: "W02", c: "fit-trening", type: "single", q: "Na jakim zbiorze dopasowuje się parametry imputera według wykładu?", options: ["Na całym zbiorze przed podziałem", "Wyłącznie na zbiorze treningowym", "Na zbiorze walidacyjnym", "Na zbiorze testowym"], correct: [1], explain: "Imputer dopasowuje się tylko na treningu, a stosuje na walidacji i teście.", src: "W02, slajd 15", note: "W02-przygotowanie-danych" },
  { id: "W02-33", w: "W02", c: "fit-trening", type: "single", q: "Gdzie według wykładu stosuje się parametry imputacji dopasowane na treningu?", options: ["Na walidacji i teście", "Tylko na zbiorze treningowym", "Na całym zbiorze przed podziałem", "Wyłącznie na zbiorze testowym"], correct: [0], explain: "Parametry imputacji dopasowuje się na treningu, a stosuje na walidacji i teście.", src: "W02, slajd 14", note: "W02-przygotowanie-danych" },
  { id: "W02-34", w: "W02", c: "fit-trening", type: "single", q: "Na jakim zbiorze według wykładu wyznacza się min i max do skalowania min–max?", options: ["Na całym zbiorze przed podziałem", "Na zbiorze treningowym", "Na zbiorze testowym", "Osobno na każdym zbiorze"], correct: [1], explain: "Min i max wyznacza się na zbiorze treningowym, tak jak parametry imputera.", src: "W02, slajd 23", note: "W02-przygotowanie-danych" },
  { id: "W02-13", w: "W02", c: "iqr", type: "calc", q: "Dla cechy Q1 = 20 i Q3 = 40. Jaka jest górna granica reguły IQR (Q3 + 1,5 × IQR)?", answer: 70, tolerance: 0.01, explain: "IQR = 40 − 20 = 20, więc 40 + 1,5 × 20 = 70.", src: "W02, slajd 17", note: "W02-przygotowanie-danych" },
  { id: "W02-14", w: "W02", c: "iqr", type: "single", q: "Czym jest IQR według wykładu?", options: ["Q3 − Q1, środkowe 50% obserwacji", "Q3 + Q1, wszystkie obserwacje", "Q1 − 1,5, dolne 25% obserwacji", "Q3 − mediana, górne 25% obserwacji"], correct: [0], explain: "IQR = Q3 − Q1, rozstęp międzykwartylowy obejmujący środkowe 50% obserwacji.", src: "W02, slajd 17", note: "W02-przygotowanie-danych" },
  { id: "W02-15", w: "W02", c: "outlier-decyzje", type: "single", q: "Kiedy według wykładu usunięcie obserwacji odstającej jest właściwą decyzją?", options: ["Gdy jest właściwym celem analizy", "Gdy jest rzadka, ale całkiem poprawna", "Gdy jest sygnałem ważnego zdarzenia", "Gdy to potwierdzony błąd techniczny"], correct: [3], explain: "Usunięcie tylko przy potwierdzonym błędzie technicznym; obserwacji nie usuwa się automatycznie.", src: "W02, slajd 18", note: "W02-przygotowanie-danych" },
  { id: "W02-16", w: "W02", c: "outlier-decyzje", type: "single", q: "Bank wykrył bardzo nietypową transakcję. Jak według wykładu należy postąpić?", options: ["Usunąć ją automatycznie ze zbioru treningowego", "Zastąpić ją średnią liczoną na zbiorze treningowym", "Ustalić, czy to błąd, rzadki przypadek, czy cel", "Zakodować ją jako rzadką kategorię „inne”"], correct: [2], explain: "Zasada: nie usuwać outlierów automatycznie; podejrzana transakcja może być sygnałem ważnego zdarzenia.", src: "W02, slajd 18", note: "W02-przygotowanie-danych" },
  { id: "W02-17", w: "W02", c: "transformacje", type: "single", q: "Cecha ma wartości ujemne i zera. Którą transformację rozkładu wskazuje wykład?", options: ["Box–Cox", "Yeo–Johnson", "Logarytm", "Pierwiastek"], correct: [1], explain: "Yeo–Johnson obsługuje także zera i wartości ujemne; Box–Cox wymaga wartości dodatnich.", src: "W02, slajd 19", note: "W02-przygotowanie-danych" },
  { id: "W02-35", w: "W02", c: "transformacje", type: "single", q: "Którą transformację wykład opisuje jako zmniejszającą wpływ bardzo dużych wartości?", options: ["Pierwiastek", "Box–Cox", "Logarytm", "Yeo–Johnson"], correct: [2], explain: "Logarytm zmniejsza wpływ bardzo dużych wartości; pierwiastek daje łagodniejszą redukcję skośności.", src: "W02, slajd 19", note: "W02-przygotowanie-danych" },
  { id: "W02-36", w: "W02", c: "transformacje", type: "single", q: "Jaką zasadę dotyczącą transformacji rozkładów podaje wykład?", options: ["Ma poprawiać model lub interpretację", "Stosuje się ją automatycznie do każdej cechy", "Dopasowuje się ją na całym zbiorze danych", "Zastępuje skalowanie cech liczbowych"], correct: [0], explain: "Transformacja jest walidowana: ma poprawiać model lub interpretację, a nie być tylko automatyczną operacją.", src: "W02, slajd 19", note: "W02-przygotowanie-danych" },
  { id: "W02-18", w: "W02", c: "kodowanie", type: "single", q: "Miasta zakodowano: Warszawa = 1, Kraków = 2, Gdańsk = 3. Jakie ryzyko opisuje wykład?", options: ["Bardzo wiele kolumn po kodowaniu", "Nieznane kategorie po wdrożeniu", "Przeciek przez target encoding", "Sztuczny porządek i fikcyjna odległość"], correct: [3], explain: "Kodowanie liczbami kategorii nominalnych tworzy porządek, którego nie ma; model może odczytać odległość między miastami.", src: "W02, slajd 21", note: "W02-przygotowanie-danych" },
  { id: "W02-19", w: "W02", c: "kodowanie", type: "single", q: "Kiedy według wykładu stosować kodowanie porządkowe?", options: ["Tylko przy naturalnej kolejności", "Dla każdej zmiennej nominalnej", "Gdy kategorii jest bardzo dużo", "Dla zmiennych typu „tak/nie”"], correct: [0], explain: "Kodowanie porządkowe (niski < średni < wysoki) tylko przy naturalnej kolejności kategorii.", src: "W02, slajd 20", note: "W02-przygotowanie-danych" },
  { id: "W02-20", w: "W02", c: "skalowanie", type: "single", q: "Dane mają silne wartości odstające. Którą metodę skalowania wykład uznaje za lepszą?", options: ["Min–max", "Standaryzację", "Skalowanie odporne", "Kodowanie binarne"], correct: [2], explain: "Skalowanie odporne opiera się na medianie i IQR; min–max jest wrażliwe na wartości odstające.", src: "W02, slajd 23", note: "W02-przygotowanie-danych" },
  { id: "W02-21", w: "W02", c: "skalowanie", type: "single", q: "Po której metodzie skalowania cecha ma średnią 0 i odchylenie 1?", options: ["Min–max", "Standaryzacji", "Skalowaniu odpornym", "Transformacji Box–Cox"], correct: [1], explain: "Standaryzacja: z = (x − μ) / σ, średnia 0, odchylenie 1; min–max daje zakres zwykle [0,1].", src: "W02, slajd 23", note: "W02-przygotowanie-danych" },
  { id: "W02-22", w: "W02", c: "wrazliwe-skala", type: "single", q: "Który algorytm wykład zalicza do MNIEJ wrażliwych na skalę cech?", options: ["Sieci neuronowe", "SVM", "Random forest", "Regresja regularyzowana"], correct: [2], explain: "Mniej wrażliwe: drzewa decyzyjne, random forest, gradient boosting na drzewach.", src: "W02, slajd 24", note: "W02-przygotowanie-danych" },
  { id: "W02-23", w: "W02", c: "wrazliwe-skala", type: "multi", q: "Które algorytmy wykład wymienia jako wrażliwe na skalę cech?", options: ["Sieci neuronowe", "Drzewa decyzyjne", "Regresja regularyzowana", "k-NN"], correct: [0, 2, 3], explain: "Wrażliwe: k-NN, SVM, PCA, regresja regularyzowana, sieci neuronowe; drzewa są mniej wrażliwe.", src: "W02, slajd 24", note: "W02-przygotowanie-danych" },
  { id: "W02-24", w: "W02", c: "feature-eng", type: "single", q: "Który warunek według wykładu musi spełniać każda nowa cecha?", options: ["Musi być binarna", "Musi być dostępna w chwili predykcji", "Musi być wyskalowana min–max", "Musi pochodzić z jednego źródła"], correct: [1], explain: "Cecha musi być dostępna w chwili predykcji, inaczej grozi przeciek.", src: "W02, slajd 25", note: "W02-przygotowanie-danych" },
  { id: "W02-37", w: "W02", c: "feature-eng", type: "single", q: "Czym według wykładu jest feature engineering?", options: ["Uzupełnianiem brakujących wartości", "Projektowaniem reprezentacji danych", "Wyborem najlepszego algorytmu dla modelu", "Skalowaniem cech do zakresu [0,1]"], correct: [1], explain: "Feature engineering to projektowanie reprezentacji danych, np. liczba dni od ostatniego zakupu zamiast samej daty.", src: "W02, slajd 25", note: "W02-przygotowanie-danych" },
  { id: "W02-38", w: "W02", c: "feature-eng", type: "single", q: "Które stwierdzenie o tworzeniu cech jest NIEZGODNE z wykładem?", options: ["Nowe cechy są często ważniejsze niż algorytm", "Dobra cecha łączy wiedzę domenową z modelem", "Algorytm jest zawsze ważniejszy niż cechy", "Cecha musi być dostępna w chwili predykcji"], correct: [2], explain: "Według slajdu nowe cechy często są ważniejsze niż wybór algorytmu.", src: "W02, slajd 25", note: "W02-przygotowanie-danych" },
  { id: "W02-25", w: "W02", c: "przeciek-kolejnosc", type: "single", q: "Która kolejność przetwarzania według wykładu prowadzi do przecieku danych?", options: ["Podział, dopasowanie na treningu, transformacja testu", "Podział, imputacja, kodowanie, skalowanie, model", "Imputacja i skalowanie na całości, potem podział", "Trening na przeszłości, test na przyszłości"], correct: [2], explain: "Transformacje na całym zbiorze przed podziałem przenoszą informację z testu do treningu.", src: "W02, slajd 28", note: "W02-przygotowanie-danych" },
  { id: "W02-39", w: "W02", c: "przeciek-kolejnosc", type: "single", q: "Która kolejność kroków jest zgodna z kompletnym pipeline’em z wykładu?", options: ["imputacja → skalowanie → podział → model", "podział → imputacja → kodowanie → skalowanie", "kodowanie → podział → imputacja → model", "podział → skalowanie → imputacja → kodowanie"], correct: [1], explain: "Pipeline z wykładu: dane surowe → podział → imputacja → kodowanie → skalowanie → model → ocena.", src: "W02, slajd 29", note: "W02-przygotowanie-danych" },
  { id: "W02-40", w: "W02", c: "przeciek-kolejnosc", type: "single", q: "Imputację i skalowanie wykonano na całym zbiorze, a potem podzielono dane na train/test. Jaki jest skutek według wykładu?", options: ["Ocena modelu pozostaje w pełni uczciwa", "Informacja z testu przecieka do treningu", "Powstaje sztuczny porządek kategorii", "Rośnie liczba kolumn po one-hot encoding"], correct: [1], explain: "Transformacje na całym zbiorze przed podziałem przenoszą informację z testu do treningu.", src: "W02, slajd 28", note: "W02-przygotowanie-danych" },
]});

// data/W03.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W03-01", w: "W03", c: "podob-vs-odl", type: "single", q: "Która cecha według wykładu dotyczy odległości, a nie podobieństwa?", options: ["Większa wartość oznacza większą zgodność", "Często mieści się w przedziale [−1,1]", "Często zaczyna się od 0, bez górnej granicy", "Przykładem jest miara cosinusowa"], correct: [2], explain: "Odległość: większa wartość to większe niepodobieństwo, często od 0 bez górnego ograniczenia.", src: "W03, slajd 4", note: "W03-miary-podobienstwa" },
  { id: "W03-02", w: "W03", c: "podob-vs-odl", type: "single", q: "Intuicja „jak bardzo są podobne?” i zakres [0,1] lub [−1,1] opisują:", options: ["odległość euklidesową", "podobieństwo", "macierz odległości", "odległość Czebyszewa"], correct: [1], explain: "Podobieństwo: większa wartość to większa zgodność, często w [0,1] lub [−1,1].", src: "W03, slajd 4", note: "W03-miary-podobienstwa" },
  { id: "W03-03", w: "W03", c: "aksjomaty", type: "single", q: "Który warunek NIE jest aksjomatem metryki?", options: ["Symetria", "Nierówność trójkąta", "Nieujemność", "Normalizacja"], correct: [3], explain: "Metryka spełnia: nieujemność, identyczność, symetrię i nierówność trójkąta.", src: "W03, slajd 7", note: "W03-miary-podobienstwa" },
  { id: "W03-04", w: "W03", c: "aksjomaty", type: "single", q: "Koszt przejścia z A do B różni się od kosztu z B do A. Który aksjomat metryki jest złamany?", options: ["Nieujemność", "Identyczność", "Symetria", "Nierówność trójkąta"], correct: [2], explain: "Symetria wymaga d(x,y) = d(y,x); tu kierunek porównania ma znaczenie.", src: "W03, slajd 8", note: "W03-miary-podobienstwa" },
  { id: "W03-05", w: "W03", c: "macierz", type: "single", q: "Co według wykładu jest prawdą o macierzy odległości?", options: ["Wiersze to obiekty, a kolumny to cechy", "Na przekątnej zwykle są jedynki", "Zawsze jest niesymetryczna", "Na przekątnej zwykle są zera"], correct: [3], explain: "Wiersze i kolumny to te same obiekty, na przekątnej zwykle zera, dla metryki symetrycznej jest symetryczna.", src: "W03, slajd 9", note: "W03-miary-podobienstwa" },
  { id: "W03-26", w: "W03", c: "macierz", type: "single", q: "Macierz odległości: A–B 2,0; A–C 5,1; A–D 4,0; B–C 3,6; B–D 2,4; C–D 1,8. Która para obiektów jest najbliżej siebie?", options: ["A i B", "B i D", "C i D", "A i C"], correct: [2], explain: "Najmniejsza wartość poza przekątną to 1,8, czyli para C i D.", src: "W03, slajd 9", note: "W03-miary-podobienstwa" },
  { id: "W03-27", w: "W03", c: "macierz", type: "single", q: "Gdzie według wykładu używana jest m.in. macierz odległości?", options: ["W skalowaniu min–max", "W klasteryzacji hierarchicznej", "W standaryzacji z = (x − μ) / σ", "W ważeniu słów metodą TF-IDF"], correct: [1], explain: "Slajd o macierzy odległości wymienia jej użycie m.in. w klasteryzacji hierarchicznej.", src: "W03, slajd 9", note: "W03-miary-podobienstwa" },
  { id: "W03-06", w: "W03", c: "minkowski", type: "single", q: "W rodzinie miar Minkowskiego odległość Manhattan odpowiada parametrowi:", options: ["p = 2", "p = 1", "p → ∞", "p = 0"], correct: [1], explain: "p = 1 to Manhattan, p = 2 euklidesowa, p → ∞ Czebyszewa.", src: "W03, slajd 14", note: "W03-miary-podobienstwa" },
  { id: "W03-07", w: "W03", c: "minkowski", type: "single", q: "Odległość Minkowskiego z p → ∞ to odległość:", options: ["Czebyszewa", "euklidesowa", "Manhattan", "Mahalanobisa"], correct: [0], explain: "Przy p → ∞ liczy się tylko największa różnica w jednym wymiarze.", src: "W03, slajd 14", note: "W03-miary-podobienstwa" },
  { id: "W03-08", w: "W03", c: "euklides-calc", type: "calc", q: "Oblicz odległość euklidesową między punktami A = (2, 3) i B = (5, 7).", answer: 5, tolerance: 0.01, explain: "√((5−2)² + (7−3)²) = √(9 + 16) = √25 = 5.", src: "W03, slajd 11", note: "W03-miary-podobienstwa" },
  { id: "W03-28", w: "W03", c: "euklides-calc", type: "calc", q: "Oblicz odległość euklidesową między punktami A = (1, 2) i B = (7, 10).", answer: 10, tolerance: 0.01, explain: "√((7−1)² + (10−2)²) = √(36 + 64) = √100 = 10.", src: "W03, slajd 10", note: "W03-miary-podobienstwa" },
  { id: "W03-09", w: "W03", c: "manhattan-calc", type: "calc", q: "Oblicz odległość Manhattan między punktami A = (2, 3) i B = (5, 7).", answer: 7, tolerance: 0.01, explain: "|5−2| + |7−3| = 3 + 4 = 7.", src: "W03, slajd 12", note: "W03-miary-podobienstwa" },
  { id: "W03-29", w: "W03", c: "manhattan-calc", type: "calc", q: "Oblicz odległość Manhattan między punktami A = (−1, 2) i B = (3, −3).", answer: 9, tolerance: 0.01, explain: "|3−(−1)| + |−3−2| = 4 + 5 = 9; liczą się wartości bezwzględne różnic.", src: "W03, slajd 12", note: "W03-miary-podobienstwa" },
  { id: "W03-10", w: "W03", c: "czebyszew", type: "calc", q: "Oblicz odległość Czebyszewa między punktami A = (2, 3) i B = (5, 7).", answer: 4, tolerance: 0.01, explain: "max(|3|, |4|) = 4; liczy się największa różnica.", src: "W03, slajd 13", note: "W03-miary-podobienstwa" },
  { id: "W03-11", w: "W03", c: "czebyszew", type: "single", q: "Której miary intuicją jest minimalna liczba ruchów króla na szachownicy?", options: ["Manhattan", "Hamminga", "Czebyszewa", "euklidesowej"], correct: [2], explain: "Czebyszew: liczy się najgorszy, najbardziej różniący wymiar.", src: "W03, slajd 13", note: "W03-miary-podobienstwa" },
  { id: "W03-12", w: "W03", c: "euklides-vs-manhattan", type: "single", q: "Co wykład mówi o odległości euklidesowej w porównaniu z Manhattan?", options: ["Ruch odbywa się tylko wzdłuż osi", "Silniej uwydatnia duże różnice", "Ignoruje różne skale cech", "Liczy tylko największą różnicę"], correct: [1], explain: "Euklidesowa silniej uwydatnia duże różnice; Manhattan mniej uwydatnia pojedyncze duże różnice.", src: "W03, slajd 10", note: "W03-miary-podobienstwa" },
  { id: "W03-30", w: "W03", c: "euklides-vs-manhattan", type: "single", q: "Która cecha według wykładu dotyczy odległości Manhattan, a nie euklidesowej?", options: ["Mierzy najkrótszy odcinek między punktami", "Dla dwóch wymiarów wynika z Pitagorasa", "Ruch wzdłuż osi, a nie po przekątnej", "Silniej uwydatnia duże różnice"], correct: [2], explain: "Manhattan to ruch po siatce ulic wzdłuż osi; pozostałe cechy opisują odległość euklidesową.", src: "W03, slajd 12", note: "W03-miary-podobienstwa" },
  { id: "W03-13", w: "W03", c: "skalowanie", type: "single", q: "Cechy: wiek 18–80 i dochód 2 000–30 000 zł, bez skalowania. Co się stanie według wykładu?", options: ["Wiek zdominuje wynik odległości", "Odległość przestanie być metryką", "Dochód zdominuje wynik odległości", "Wynik się nie zmieni po skalowaniu"], correct: [2], explain: "Cechy w dużych jednostkach dominują odległość; najbliższy sąsiad może być artefaktem skali.", src: "W03, slajd 16", note: "W03-miary-podobienstwa" },
  { id: "W03-14", w: "W03", c: "skalowanie", type: "single", q: "Która metoda skalowania daje średnią 0 i odchylenie standardowe 1?", options: ["Skalowanie min–max", "Standaryzacja", "Ważenie cech", "Ważenie TF-IDF"], correct: [1], explain: "Standaryzacja: z = (x − μ) / σ; min–max daje wartości zwykle w [0,1].", src: "W03, slajd 18", note: "W03-miary-podobienstwa" },
  { id: "W03-15", w: "W03", c: "mahalanobis", type: "single", q: "Która odległość uwzględnia skalę cech i ich korelacje przez macierz kowariancji?", options: ["Mahalanobisa", "Manhattan", "Hamminga", "Czebyszewa"], correct: [0], explain: "Mahalanobis mierzy odległość względem naturalnej zmienności danych, używając S⁻¹.", src: "W03, slajd 19", note: "W03-miary-podobienstwa" },
  { id: "W03-16", w: "W03", c: "mahalanobis", type: "single", q: "Co NIE jest ograniczeniem odległości Mahalanobisa według wykładu?", options: ["Problemy przy małej liczbie obserwacji", "Wrażliwość na obserwacje odstające", "Niestabilna odwrotność macierzy", "Pomijanie korelacji między cechami"], correct: [3], explain: "Mahalanobis właśnie uwzględnia korelacje; pozostałe to ograniczenia ze slajdu 20.", src: "W03, slajd 20", note: "W03-miary-podobienstwa" },
  { id: "W03-17", w: "W03", c: "smc-jaccard", type: "single", q: "Porównujemy koszyki zakupowe (rzadkie zbiory). Którą miarę wykład poleca?", options: ["Simple Matching Coefficient", "Odległość Hamminga", "Jaccard", "Odległość euklidesową"], correct: [2], explain: "Jaccard ignoruje wspólne zera, dlatego jest dobry dla rzadkich zbiorów: koszyki, tagi, choroby, słowa.", src: "W03, slajd 22", note: "W03-miary-podobienstwa" },
  { id: "W03-18", w: "W03", c: "smc-jaccard", type: "single", q: "Czym różni się SMC od współczynnika Jaccarda?", options: ["SMC ignoruje wspólne jedynki", "SMC uwzględnia wspólne zera", "SMC działa tylko dla tekstu", "SMC wymaga macierzy kowariancji"], correct: [1], explain: "SMC = (a+d)/(a+b+c+d) liczy wspólne jedynki i zera; Jaccard ignoruje wspólne zera.", src: "W03, slajd 22", note: "W03-miary-podobienstwa" },
  { id: "W03-19", w: "W03", c: "binarne", type: "single", q: "Produkt w koszyku, choroba, tag dokumentu to według wykładu przykłady danych binarnych:", options: ["asymetrycznych", "symetrycznych", "mieszanych", "sekwencyjnych"], correct: [0], explain: "W danych asymetrycznych ważna jest obecność cechy, a wspólne braki niewiele mówią.", src: "W03, slajd 21", note: "W03-miary-podobienstwa" },
  { id: "W03-31", w: "W03", c: "binarne", type: "single", q: "Odpowiedź tak/nie w ankiecie to według wykładu przykład danych binarnych:", options: ["asymetrycznych", "symetrycznych", "mieszanych", "sekwencyjnych"], correct: [1], explain: "W danych symetrycznych zarówno 1, jak i 0 mają znaczenie.", src: "W03, slajd 21", note: "W03-miary-podobienstwa" },
  { id: "W03-32", w: "W03", c: "binarne", type: "single", q: "Co NIE jest prawdą o danych binarnych asymetrycznych według wykładu?", options: ["Najważniejsza jest obecność cechy", "Wspólne braki zwykle niewiele mówią", "Przykładem jest tag dokumentu", "Wspólne zera są zwykle informacyjne"], correct: [3], explain: "W danych asymetrycznych wspólne braki niewiele mówią; informacyjne wspólne zera dotyczą danych symetrycznych.", src: "W03, slajd 21", note: "W03-miary-podobienstwa" },
  { id: "W03-20", w: "W03", c: "jaccard-calc", type: "calc", q: "Koszyk A = {chleb, masło, mleko, kawa}, koszyk B = {chleb, mleko, cukier}. Oblicz odległość Jaccarda (1 − J).", answer: 0.6, tolerance: 0.01, explain: "|A∩B| = 2, |A∪B| = 5, J = 0,40, odległość = 1 − 0,40 = 0,60.", src: "W03, slajd 23", note: "W03-miary-podobienstwa" },
  { id: "W03-33", w: "W03", c: "jaccard-calc", type: "calc", q: "Koszyk A = {chleb, mleko, kawa, cukier}, koszyk B = {mleko, cukier, masło, jajka}. Oblicz współczynnik Jaccarda J(A,B).", answer: 0.333, tolerance: 0.01, explain: "|A∩B| = 2 (mleko, cukier), |A∪B| = 6, J = 2/6 ≈ 0,33.", src: "W03, slajd 22", note: "W03-miary-podobienstwa" },
  { id: "W03-21", w: "W03", c: "hamming", type: "calc", q: "Oblicz odległość Hamminga między ciągami x = 101101 i y = 111001.", answer: 2, tolerance: 0, explain: "Ciągi różnią się na pozycjach 2 i 4.", src: "W03, slajd 24", note: "W03-miary-podobienstwa" },
  { id: "W03-34", w: "W03", c: "hamming", type: "single", q: "Co NIE jest prawdą o odległości Hamminga według wykładu?", options: ["Liczy pozycje, na których ciągi się różnią", "Stosowana dla ciągów o tej samej długości", "Można ją znormalizować przez długość ciągu", "Liczy wstawienia, usunięcia i zamiany"], correct: [3], explain: "Wstawienia, usunięcia i zamiany liczy odległość Levenshteina; Hamming porównuje ciągi pozycja po pozycji.", src: "W03, slajd 24", note: "W03-miary-podobienstwa" },
  { id: "W03-35", w: "W03", c: "hamming", type: "calc", q: "Ciągi x = 10110100 i y = 10011110. Oblicz odległość Hamminga znormalizowaną przez długość ciągu.", answer: 0.375, tolerance: 0.01, explain: "Różnice na pozycjach 3, 5 i 7, więc d_H = 3; po normalizacji 3/8 = 0,375.", src: "W03, slajd 24", note: "W03-miary-podobienstwa" },
  { id: "W03-22", w: "W03", c: "cosinus", type: "single", q: "Dlaczego podobieństwo cosinusowe dobrze sprawdza się dla dokumentów o różnej długości?", options: ["Bo liczy największą różnicę cech", "Bo uwzględnia korelacje słów", "Bo porównuje kierunek wektorów", "Bo liczy wspólne zera wektorów"], correct: [2], explain: "Cosinus porównuje kierunek wektorów, a nie ich długość.", src: "W03, slajd 25", note: "W03-miary-podobienstwa" },
  { id: "W03-36", w: "W03", c: "cosinus", type: "single", q: "Która miara porównuje kierunek wektorów, a nie ich długość?", options: ["Odległość euklidesowa", "Podobieństwo cosinusowe", "Odległość Mahalanobisa", "Simple Matching Coefficient"], correct: [1], explain: "Cosinus porównuje kierunek wektorów, dlatego dobrze sprawdza się dla dokumentów o różnej długości.", src: "W03, slajd 25", note: "W03-miary-podobienstwa" },
  { id: "W03-37", w: "W03", c: "cosinus", type: "single", q: "Dokumenty zapisano jako wektory bag-of-words. Dlaczego według wykładu zwykłe porównanie euklidesowe bywa tu problemem?", options: ["Wektory tekstowe mają mało wymiarów", "Długość dokumentu może je zaburzać", "Wektory tekstowe są zwykle gęste", "TF-IDF pomija słowa charakterystyczne"], correct: [1], explain: "Długość dokumentu może zaburzać porównanie euklidesowe; wektory tekstowe są wysokowymiarowe i rzadkie.", src: "W03, slajd 25", note: "W03-miary-podobienstwa" },
  { id: "W03-23", w: "W03", c: "dobor-miary", type: "single", q: "Profil klienta: wiek, region, status, dochód, zgody marketingowe. Którą miarę wykład wskazuje?", options: ["Levenshteina", "Gowera", "Jaccarda", "Mahalanobisa"], correct: [1], explain: "Gower: jedna miara dla danych mieszanych, średnia ważona częściowych niepodobieństw.", src: "W03, slajd 26", note: "W03-miary-podobienstwa" },
  { id: "W03-24", w: "W03", c: "dobor-miary", type: "single", q: "Dwa podobne przebiegi aktywności o różnym tempie najlepiej porównać miarą:", options: ["Levenshteina", "Hamminga", "Jaccarda", "DTW"], correct: [3], explain: "DTW porównuje szeregi czasowe z przesunięciami w czasie; Levenshtein służy do tekstów.", src: "W03, slajd 27", note: "W03-miary-podobienstwa" },
  { id: "W03-25", w: "W03", c: "klatwa", type: "single", q: "Czym jest koncentracja odległości w wysokim wymiarze?", options: ["Odległości stają się coraz bardziej ujemne", "Wszystkie cechy dostają równe wagi", "Dane skupiają się w jednym klastrze", "Najbliższy i najdalszy punkt są podobnie odległe"], correct: [3], explain: "W wysokim wymiarze odległości do najbliższego i najdalszego punktu stają się relatywnie podobne.", src: "W03, slajd 28", note: "W03-miary-podobienstwa" },
  { id: "W03-38", w: "W03", c: "klatwa", type: "single", q: "Co według wykładu NIE dzieje się w wysokim wymiarze?", options: ["Dane stają się rzadkie", "Metody sąsiedztwa tracą stabilność", "Łatwiej znaleźć lokalne sąsiedztwo", "Przestrzeń rośnie bardzo szybko"], correct: [2], explain: "Dane stają się rzadkie, dlatego coraz trudniej znaleźć lokalne sąsiedztwo.", src: "W03, slajd 28", note: "W03-miary-podobienstwa" },
  { id: "W03-39", w: "W03", c: "klatwa", type: "single", q: "k-NN na danych z bardzo wieloma cechami traci stabilność. Czego według wykładu może to wymagać?", options: ["Dodania kolejnych cech", "Selekcji lub redukcji cech", "Rezygnacji ze skalowania", "Przejścia na miarę Hamminga"], correct: [1], explain: "W wysokim wymiarze k-NN, klasteryzacja i rekomendacje mogą wymagać selekcji lub redukcji cech.", src: "W03, slajd 28", note: "W03-miary-podobienstwa" },
]});

// data/W04.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W04-01", w: "W04", c: "wymiar-def", type: "single", q: "Czym według wykładu jest wymiar danych?", options: ["Liczbą obserwacji w zbiorze danych", "Liczbą cech opisujących jedną obserwację", "Liczbą klas w zmiennej celu", "Liczbą składowych głównych PCA"], correct: [1], explain: "Wymiar to liczba cech opisujących pojedynczą obserwację; jest własnością reprezentacji.", src: "W04, slajd 3", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-26", w: "W04", c: "wymiar-def", type: "single", q: "Które stwierdzenie o wymiarze danych jest zgodne z wykładem?", options: ["Cechą może być wyłącznie liczba lub kategoria", "Wymiar jest stałą własnością samego obiektu", "Wymiar jest własnością reprezentacji obiektu", "Wymiar to liczba obserwacji w jednym zbiorze"], correct: [2], explain: "Wymiar jest własnością reprezentacji, a nie samego obiektu. Cechą może być też data, słowo lub piksel.", src: "W04, slajd 3", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-02", w: "W04", c: "klatwa", type: "single", q: "Co NIE jest skutkiem klątwy wymiarowości według wykładu?", options: ["Przestrzeń danych szybko się rozrzedza", "Odległości stają się mniej rozróżnialne", "Model staje się łatwiejszy do interpretacji", "Potrzeba wykładniczo więcej obserwacji"], correct: [2], explain: "Wysoki wymiar utrudnia interpretację; klątwa to rozrzedzenie przestrzeni i słabsze rozróżnianie odległości.", src: "W04, slajd 6", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-27", w: "W04", c: "klatwa", type: "single", q: "Jak nazywa się zjawisko, w którym wraz ze wzrostem liczby wymiarów przestrzeń szybko się rozrzedza?", options: ["redundancja statystyczna", "przeciek danych", "silna współliniowość", "klątwa wymiarowości"], correct: [3], explain: "Klątwa wymiarowości: przestrzeń się rozrzedza, a odległości między punktami stają się mniej rozróżnialne.", src: "W04, slajd 6", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-28", w: "W04", c: "klatwa", type: "single", q: "Które metody według wykładu mogą tracić jakość z powodu klątwy wymiarowości?", options: ["k-NN, k-means i DBSCAN", "Lasso, Ridge i Elastic Net", "forward, backward i RFE", "ANOVA, chi-kwadrat i MI"], correct: [0], explain: "W wysokim wymiarze odległości stają się mniej rozróżnialne. Dlatego k-NN, k-means i DBSCAN mogą tracić jakość.", src: "W04, slajd 6", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-03", w: "W04", c: "rodzaje-cech", type: "single", q: "Cecha, która powtarza informację zawartą w innych cechach, to cecha:", options: ["zaszumiona", "stała", "identyfikacyjna", "redundantna"], correct: [3], explain: "Cecha redundantna powtarza informację z innych cech, np. wzrost_cm i wzrost_m.", src: "W04, slajd 7", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-04", w: "W04", c: "rodzaje-cech", type: "single", q: "Czym według wykładu jest cecha zaszumiona?", options: ["Ma jedną wartość dla wszystkich obserwacji", "Zawiera głównie przypadkową zmienność", "Powtarza informację z innej kolumny", "Jest niedostępna w chwili predykcji"], correct: [1], explain: "Zaszumiona cecha zawiera głównie przypadkową zmienność, a nie sygnał związany z celem.", src: "W04, slajd 7", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-05", w: "W04", c: "selekcja-ekstrakcja", type: "single", q: "Czym różni się ekstrakcja cech od selekcji cech?", options: ["Ekstrakcja tworzy nowe zmienne, np. składowe PCA", "Ekstrakcja wybiera podzbiór oryginalnych zmiennych", "Ekstrakcja lepiej zachowuje interpretowalność", "Ekstrakcji nie można łączyć z selekcją"], correct: [0], explain: "Selekcja wybiera podzbiór oryginalnych zmiennych, ekstrakcja tworzy nowe, np. składowe PCA.", src: "W04, slajd 8", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-06", w: "W04", c: "selekcja-ekstrakcja", type: "single", q: "Bank buduje audytowalny model ryzyka i musi znać konkretne zmienne decyzyjne. Co wybrać według wykładu?", options: ["Ekstrakcję cech metodą PCA", "Ekstrakcję cech metodą SVD", "Selekcję cech", "Wizualizację cech w 2D"], correct: [2], explain: "Selekcja: gdy ważna jest interpretacja, znajomość zmiennych i cechy audytowalne, np. model ryzyka.", src: "W04, slajd 9", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-07", w: "W04", c: "stala-wariancja", type: "single", q: "Co według wykładu oznacza cecha o wariancji równej 0?", options: ["Cechę silnie skorelowaną z targetem", "Brak zdolności rozróżniania obiektów", "Cechę z informacją z przyszłości", "Cechę o rzadkiej, ważnej wartości"], correct: [1], explain: "Cecha stała ma tę samą wartość dla wszystkich obserwacji, więc nie rozróżnia obiektów.", src: "W04, slajd 11", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-29", w: "W04", c: "stala-wariancja", type: "single", q: "Cecha jest prawie stała, ale jej rzadka wartość oznacza oszustwo. Co zaleca wykład?", options: ["Usunąć ją automatycznie jako cechę stałą", "Decyzję oprzeć na kontekście domenowym", "Zastąpić ją pierwszą składową PCA", "Zostawić ją dopiero po standaryzacji"], correct: [1], explain: "Cecha prawie stała to tylko kandydat do usunięcia. Rzadka wartość może oznaczać ważne zdarzenie, więc decyzja wymaga kontekstu domenowego.", src: "W04, slajd 11", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-08", w: "W04", c: "przeciek-cechy", type: "single", q: "W modelu churn użyto cechy „data rozwiązania umowy”. Co wykład mówi o takiej cesze?", options: ["Jest cechą stałą do usunięcia", "Jest duplikatem technicznym", "Jest dozwolona po standaryzacji", "Jest cechą z przyszłości, niedozwoloną"], correct: [3], explain: "Cecha z przyszłości zawiera wiedzę niedostępną w chwili decyzji; cecha musi być dostępna przed predykcją.", src: "W04, slajd 13", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-09", w: "W04", c: "przeciek-cechy", type: "single", q: "Dlaczego ID klienta lub PESEL zwykle nie powinny być cechami modelu?", options: ["Mogą prowadzić do zapamiętywania", "Mają zawsze zerową wariancję", "Są silnie skorelowane z targetem", "Są niedostępne przy integracji danych"], correct: [0], explain: "Identyfikatory są potrzebne do integracji danych, ale jako cechy mogą prowadzić do zapamiętywania.", src: "W04, slajd 13", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-10", w: "W04", c: "filter", type: "single", q: "Która rodzina metod selekcji ocenia cechy przed modelem i jest szybka oraz skalowalna?", options: ["wrapper", "embedded", "filter", "ekstrakcja"], correct: [2], explain: "Filter: ocena cech przed modelem (korelacja, χ², ANOVA, MI), szybkie i skalowalne.", src: "W04, slajd 15", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-11", w: "W04", c: "filter", type: "single", q: "Jakie jest typowe ograniczenie metod filter według wykładu?", options: ["Wysoki koszt obliczeniowy", "Często pomijają interakcje między cechami", "Selekcja zachodzi podczas uczenia modelu", "Ryzyko przeuczenia selekcji do walidacji"], correct: [1], explain: "Filter ocenia cechy niezależnie od modelu, więc często pomija interakcje między cechami.", src: "W04, slajd 16", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-12", w: "W04", c: "wrapper", type: "single", q: "Podzbiory cech oceniane na podstawie wyniku konkretnego modelu to metody:", options: ["embedded", "filter", "ekstrakcji", "wrapper"], correct: [3], explain: "Wrapper ocenia podzbiory przez model: forward, backward, RFE; dokładne, ale kosztowne.", src: "W04, slajd 21", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-13", w: "W04", c: "wrapper", type: "single", q: "Która metoda startuje od pełnego zbioru cech i je usuwa?", options: ["backward elimination", "forward selection", "mutual information", "permutation importance"], correct: [0], explain: "Backward elimination startuje od pełnego zbioru; forward selection od pustego i dodaje cechy.", src: "W04, slajd 21", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-14", w: "W04", c: "embedded", type: "single", q: "Co charakteryzuje metody embedded?", options: ["Ocena cech przed modelem, bez uczenia", "Ocena wszystkich podzbiorów przez model", "Selekcja zachodzi podczas uczenia modelu", "Tworzenie nowych, ortogonalnych osi"], correct: [2], explain: "Embedded: selekcja podczas uczenia (Lasso, drzewa, boosting), kompromis kosztu i jakości.", src: "W04, slajd 23", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-30", w: "W04", c: "embedded", type: "single", q: "Które metody wykład podaje jako przykłady metod embedded?", options: ["forward, backward i RFE", "Lasso, drzewa i boosting", "korelacja, chi-kwadrat i MI", "PCA, SVD i wizualizacja 2D"], correct: [1], explain: "Embedded to np. Lasso, Elastic Net, drzewa, random forest i boosting. Forward, backward i RFE to metody wrapper.", src: "W04, slajd 23", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-31", w: "W04", c: "embedded", type: "single", q: "Jak wykład umiejscawia metody embedded względem pozostałych rodzin selekcji?", options: ["Osobny krok wykonywany przed modelem", "Wynik niezależny od modelu i parametrów", "Często kompromis między filter i wrapper", "Dokładniejsze i droższe niż metody wrapper"], correct: [2], explain: "Embedded to często kompromis między filter i wrapper. Wynik nadal zależy od modelu i parametrów.", src: "W04, slajd 23", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-15", w: "W04", c: "test-filter", type: "single", q: "Cecha jest liczbowa, a target kategoryczny. Który test filter pasuje według wykładu?", options: ["test chi-kwadrat", "ANOVA", "korelacja Spearmana", "RFE"], correct: [1], explain: "ANOVA: cecha liczbowa i target kategoryczny; χ²: cecha kategoryczna lub zliczeniowa.", src: "W04, slajd 19", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-16", w: "W04", c: "test-filter", type: "single", q: "Która miara filter mierzy redukcję niepewności i może wykrywać zależności nieliniowe?", options: ["korelacja Pearsona", "test ANOVA", "mutual information", "test chi-kwadrat"], correct: [2], explain: "Mutual information mierzy redukcję niepewności i może wykrywać zależności nieliniowe.", src: "W04, slajd 19", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-17", w: "W04", c: "pearson-spearman", type: "single", q: "Czym różni się korelacja Spearmana od Pearsona?", options: ["Mierzy zależność monotoniczną na rangach", "Mierzy wyłącznie zależność liniową", "Jest wrażliwsza na wartości odstające", "Mierzy redukcję niepewności"], correct: [0], explain: "Spearman: zależność monotoniczna na rangach; Pearson: liniowa i wrażliwsza na outliery.", src: "W04, slajd 17", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-32", w: "W04", c: "pearson-spearman", type: "single", q: "Zależność cechy z targetem jest rosnąca, ale nie jest liniowa. Która miara ją uchwyci według wykładu?", options: ["korelacja Pearsona", "ładunki składowych PCA", "korelacja Spearmana", "test chi-kwadrat"], correct: [2], explain: "Spearman mierzy zależność monotoniczną na rangach, więc uchwyci zależność rosnącą bez prostej liniowej. Pearson mierzy zależność liniową.", src: "W04, slajd 17", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-33", w: "W04", c: "pearson-spearman", type: "single", q: "Który opis korelacji Pearsona jest zgodny z wykładem?", options: ["Zależność monotoniczna liczona na rangach", "Redukcja niepewności, także nieliniowa", "Test dla cechy i targetu kategorycznego", "Zależność liniowa, wrażliwa na outliery"], correct: [3], explain: "Pearson mierzy siłę zależności liniowej i jest wrażliwszy na wartości odstające. Rangi to Spearman, redukcja niepewności to MI.", src: "W04, slajd 17", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-18", w: "W04", c: "top-k", type: "single", q: "Na jakim zbiorze dobiera się liczbę k lub próg w rankingu cech?", options: ["Na zbiorze testowym", "Na całym zbiorze danych", "Na zbiorze walidacyjnym", "Na zbiorze treningowym bez walidacji"], correct: [2], explain: "k jest hiperparametrem; k lub próg dobieramy w walidacji, nie na teście.", src: "W04, slajd 20", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-34", w: "W04", c: "top-k", type: "single", q: "Czym według wykładu jest liczba k przy wyborze top-k cech?", options: ["Liczbą składowych o EVR powyżej 95%", "Hiperparametrem procesu modelowania", "Stałą wynikającą z testu chi-kwadrat", "Liczbą obserwacji w walidacji"], correct: [1], explain: "Liczba k jest hiperparametrem procesu modelowania. Dobiera się ją, tak jak próg, w walidacji.", src: "W04, slajd 20", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-19", w: "W04", c: "regularyzacja", type: "single", q: "Która regularyzacja może zerować współczynniki i działać jak selekcja cech?", options: ["L2 / Ridge", "L1 / Lasso", "PCA", "Permutation importance"], correct: [1], explain: "L1 / Lasso może zerować współczynniki; L2 / Ridge je zmniejsza, ale zwykle nie zeruje.", src: "W04, slajd 24", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-20", w: "W04", c: "regularyzacja", type: "single", q: "Co według wykładu robi Elastic Net?", options: ["Zeruje wszystkie słabe współczynniki", "Tylko zmniejsza współczynniki bez zerowania", "Łączy selekcję L1 ze stabilizacją L2", "Permutuje cechy na zbiorze walidacyjnym"], correct: [2], explain: "Elastic Net łączy selekcję L1 ze stabilizacją L2.", src: "W04, slajd 24", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-21", w: "W04", c: "permutation", type: "single", q: "Po permutacji jednej cechy jakość modelu spadła bardzo mało. Co to oznacza według wykładu?", options: ["Cecha jest bardzo ważna", "Cecha jest przyczyną wyniku", "Cecha zawiera przeciek danych", "Cecha jest zastępowalna albo nieużywana"], correct: [3], explain: "Duży spadek oznacza ważną cechę; mały spadek oznacza cechę zastępowalną albo nieużywaną.", src: "W04, slajd 26", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-35", w: "W04", c: "permutation", type: "single", q: "Metoda, która losowo permutuje wartości jednej cechy i mierzy spadek jakości modelu, to:", options: ["permutation importance", "ważność Gini w drzewach", "backward elimination", "mutual information"], correct: [0], explain: "Permutation importance niszczy związek cechy z targetem i mierzy spadek jakości. Gini to suma spadków nieczystości w drzewach.", src: "W04, slajd 26", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-36", w: "W04", c: "permutation", type: "single", q: "Na jakim zbiorze oblicza się permutation importance według wykładu?", options: ["Tylko na zbiorze treningowym", "Na całym zbiorze przed podziałem", "Na treningowym po imputacji braków", "Na walidacyjnym lub testowym"], correct: [3], explain: "Wynik bazowy i spadek jakości mierzy się na zbiorze walidacyjnym lub testowym, a nie treningowym.", src: "W04, slajd 26", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-22", w: "W04", c: "pca", type: "single", q: "Które stwierdzenie o PCA jest zgodne z wykładem?", options: ["PCA wybiera podzbiór oryginalnych cech", "PC1 zachowuje największą wariancję", "PCA korzysta z etykiet klas", "Kolejne PC opisują coraz więcej wariancji"], correct: [1], explain: "PC1 ma największą wariancję, kolejne składowe są ortogonalne i opisują coraz mniej; PCA nie zna etykiet.", src: "W04, slajd 27", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-23", w: "W04", c: "pca", type: "single", q: "Co w PCA określa wartość własna λ?", options: ["Kierunek składowej głównej", "Wektor średnich wartości cech", "Wariancję wyjaśnianą przez składową", "Udział cechy w składowej (ładunek)"], correct: [2], explain: "Wektor własny v to kierunek składowej, a wartość własna λ mówi, ile wariancji reprezentuje składowa.", src: "W04, slajd 28", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-24", w: "W04", c: "evr", type: "calc", q: "Wartości własne czterech składowych PCA wynoszą 5, 3, 1,5 i 0,5. Oblicz EVR dla PC1 (jako ułamek, np. 0.25).", answer: 0.5, tolerance: 0.01, explain: "EVR₁ = λ₁ / Σλⱼ = 5 / (5 + 3 + 1,5 + 0,5) = 5 / 10 = 0,5.", src: "W04, slajd 29", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-37", w: "W04", c: "evr", type: "single", q: "Co według wykładu mówi wskaźnik EVRₖ?", options: ["Jaki udział wariancji zachowuje PCₖ", "Jaki jest kierunek składowej PCₖ", "Jaki jest udział cechy w składowej PCₖ", "Ile cech ma wysoki ładunek w PCₖ"], correct: [0], explain: "EVRₖ = λₖ / Σλⱼ mówi, jaki udział wariancji zachowuje PCₖ. Udział cech w składowych pokazują ładunki PCA.", src: "W04, slajd 29", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-38", w: "W04", c: "evr", type: "single", q: "Jak wykład traktuje próg 90–95% wariancji przy doborze liczby składowych PCA?", options: ["Jako twardą regułę wymaganą przez PCA", "Jako heurystykę, a nie prawo", "Jako próg dla ładunków PCA", "Jako minimalną wartość λ dla PC1"], correct: [1], explain: "Dobór liczby składowych, np. 90–95% wariancji, to heurystyka, a nie prawo.", src: "W04, slajd 29", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-25", w: "W04", c: "pipeline", type: "single", q: "Co wykład nazywa błędem krytycznym w pipeline redukcji wymiaru?", options: ["Skalowanie danych zawsze przed wykonaniem PCA", "PCA na całym zbiorze przed podziałem danych", "Imputację braków przed selekcją cech modelu", "Ocenę gotowego modelu na zbiorze testowym"], correct: [1], explain: "Kolejność: podział, imputacja i skalowanie, selekcja lub PCA, model, ocena na teście.", src: "W04, slajd 30", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-39", w: "W04", c: "pipeline", type: "single", q: "Jaka jest kolejność kroków w pipeline redukcji wymiaru według wykładu?", options: ["Imputacja i skalowanie → selekcja lub PCA → podział → model → ocena", "Podział → selekcja lub PCA → imputacja i skalowanie → model → ocena", "Podział → imputacja i skalowanie → selekcja lub PCA → model → ocena", "Selekcja lub PCA → podział → imputacja i skalowanie → model → ocena"], correct: [2], explain: "Najpierw podział danych, potem imputacja i skalowanie, selekcja lub PCA, model i ocena na teście.", src: "W04, slajd 30", note: "W04-redukcja-wymiarowosci" },
  { id: "W04-40", w: "W04", c: "pipeline", type: "single", q: "Zespół wykonał PCA na całym zbiorze, a dopiero potem podzielił dane. Jak ocenia to wykład?", options: ["To poprawne, bo PCA nie zna etykiet", "To błąd krytyczny w pipeline", "To poprawne po standaryzacji danych", "To błąd tylko przy selekcji cech"], correct: [1], explain: "Selekcja cech lub PCA na całym zbiorze przed podziałem to błąd krytyczny. Dotyczy to także PCA, choć nie zna etykiet.", src: "W04, slajd 30", note: "W04-redukcja-wymiarowosci" },
]});

// data/W05.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W05-01", w: "W05", c: "klasyfikacja-def", type: "single", q: "Przypisanie obiektu do jednej z wcześniej zdefiniowanych klas to:", options: ["klasteryzacja", "redukcja wymiaru", "klasyfikacja", "reguły asocjacyjne"], correct: [2], explain: "Klasyfikacja przypisuje obiekt do jednej z klas zdefiniowanych wcześniej.", src: "W05, slajd 3", note: "W05-klasyfikacja" },
  { id: "W05-02", w: "W05", c: "klasyfikacja-def", type: "single", q: "Czym według wykładu klasyfikacja różni się od klasteryzacji?", options: ["W klasyfikacji klasy są znane z góry", "W klasyfikacji nie ma danych treningowych", "Klasyfikacja zwraca tylko wartości liczbowe", "Klasyfikacja nie wymaga etykiet w danych"], correct: [0], explain: "W klasyfikacji klasy są znane z góry, a model uczy się na przykładach z prawidłową klasą.", src: "W05, slajd 3", note: "W05-klasyfikacja" },
  { id: "W05-03", w: "W05", c: "rodzaje", type: "single", q: "Jeden obiekt może mieć kilka etykiet jednocześnie. Jaki to rodzaj klasyfikacji?", options: ["binarna", "wieloklasowa", "stratyfikowana", "wieloetykietowa"], correct: [3], explain: "Wieloetykietowa: kilka etykiet naraz; wieloklasowa: wybierana jest jedna z wielu klas.", src: "W05, slajd 5", note: "W05-klasyfikacja" },
  { id: "W05-04", w: "W05", c: "rodzaje", type: "single", q: "Dokument trafia do dokładnie jednej z ośmiu kategorii tematycznych. To klasyfikacja:", options: ["binarna", "wieloklasowa", "wieloetykietowa", "grupowa"], correct: [1], explain: "Wieloklasowa: więcej niż dwie klasy, wybierana jest jedna, np. kategoria dokumentu.", src: "W05, slajd 5", note: "W05-klasyfikacja" },
  { id: "W05-05", w: "W05", c: "horyzont", type: "single", q: "„Co poniedziałek przewidujemy odejście klienta w ciągu 30 dni”. Co tu oznacza „co poniedziałek”?", options: ["horyzont predykcji", "jednostkę analizy", "moment predykcji", "etykietę klasy"], correct: [2], explain: "Moment predykcji to chwila decyzji; horyzont to okres zdarzenia (30 dni).", src: "W05, slajd 7", note: "W05-klasyfikacja" },
  { id: "W05-26", w: "W05", c: "horyzont", type: "single", q: "Okres, którego dotyczy przewidywane zdarzenie, to według wykładu:", options: ["moment predykcji", "jednostka analizy", "horyzont predykcji", "walidacja czasowa"], correct: [2], explain: "Horyzont predykcji to okres zdarzenia, np. 30 dni; moment predykcji to chwila decyzji.", src: "W05, slajd 7", note: "W05-klasyfikacja" },
  { id: "W05-27", w: "W05", c: "horyzont", type: "single", q: "Bank ocenia każdą transakcję kartą tuż przed jej akceptacją. Czym jest tu pojedyncza transakcja?", options: ["horyzontem predykcji", "jednostką analizy", "momentem predykcji", "etykietą klasy"], correct: [1], explain: "Jednostka analizy to pojedynczy przypadek, dla którego model wydaje predykcję, np. transakcja.", src: "W05, slajd 7", note: "W05-klasyfikacja" },
  { id: "W05-06", w: "W05", c: "podzial", type: "single", q: "Do czego według wykładu służy zbiór walidacyjny?", options: ["Do uczenia parametrów modelu i transformacji", "Do jednorazowej końcowej oceny modelu", "Do dopasowania standaryzacji przed podziałem", "Do doboru modelu, hiperparametrów i progu"], correct: [3], explain: "Trening uczy, walidacja wybiera warianty, test ocenia końcowo.", src: "W05, slajd 9", note: "W05-klasyfikacja" },
  { id: "W05-07", w: "W05", c: "podzial", type: "single", q: "Zespół kilka razy zmieniał model po obejrzeniu wyniku na zbiorze testowym. Co z tego wynika?", options: ["Test przestaje być niezależnym testem", "Test staje się zbiorem stratyfikowanym", "Model jest mniej podatny na przeuczenie", "Wynik testu staje się bardziej wiarygodny"], correct: [0], explain: "Jeśli test wpływa na wybór modelu, przestaje być niezależny.", src: "W05, slajd 9", note: "W05-klasyfikacja" },
  { id: "W05-08", w: "W05", c: "walidacja-schemat", type: "single", q: "Ten sam pacjent nie może trafić jednocześnie do treningu i walidacji. Który to schemat?", options: ["walidacja stratyfikowana", "walidacja czasowa", "walidacja grupowa", "walidacja krzyżowa k-fold"], correct: [2], explain: "Walidacja grupowa: ten sam klient, pacjent lub urządzenie nie trafia do obu zbiorów.", src: "W05, slajd 11", note: "W05-klasyfikacja" },
  { id: "W05-28", w: "W05", c: "walidacja-schemat", type: "single", q: "Model trenowany jest na danych z lat 2022–2023 i sprawdzany na danych z 2024 roku. Który to schemat walidacji?", options: ["walidacja grupowa", "walidacja stratyfikowana", "walidacja czasowa", "walidacja krzyżowa k-fold"], correct: [2], explain: "Walidacja czasowa: trening na danych historycznych, walidacja na późniejszym okresie.", src: "W05, slajd 11", note: "W05-klasyfikacja" },
  { id: "W05-29", w: "W05", c: "walidacja-schemat", type: "single", q: "Co według wykładu zapewnia walidacja stratyfikowana?", options: ["Zachowanie proporcji klas w podzbiorach", "Rozdzielenie danych tego samego klienta", "Walidację na danych z późniejszego okresu", "Uczenie modelu kolejno na k foldach"], correct: [0], explain: "Stratyfikowana zachowuje proporcje klas, co pomaga przy rzadkich zdarzeniach.", src: "W05, slajd 11", note: "W05-klasyfikacja" },
  { id: "W05-09", w: "W05", c: "przeciek", type: "single", q: "Które z poniższych NIE jest źródłem przecieku danych wymienionym na wykładzie?", options: ["Selekcja cech z użyciem danych testowych", "Transformacje dopasowane na całym zbiorze", "Cecha powstała po momencie predykcji", "Dobór progu na zbiorze walidacyjnym"], correct: [3], explain: "Dobór progu na walidacji to poprawna praktyka; pozostałe to źródła przecieku.", src: "W05, slajd 12", note: "W05-klasyfikacja" },
  { id: "W05-30", w: "W05", c: "przeciek", type: "single", q: "Model churn używa cechy „data zamknięcia konta”. Które źródło przecieku danych tu występuje?", options: ["Transformacje na całym zbiorze", "Informacja z przyszłości", "Selekcja cech na danych testowych", "Te same obiekty w treningu i teście"], correct: [1], explain: "Konto zamyka się po odejściu klienta, więc cecha powstaje po momencie predykcji.", src: "W05, slajd 12", note: "W05-klasyfikacja" },
  { id: "W05-31", w: "W05", c: "przeciek", type: "single", q: "Standaryzację dopasowano na całym zbiorze przed podziałem na trening i test. Jaki jest skutek?", options: ["Wynik testu jest zbyt optymistyczny", "Wynik testu jest zaniżony przez szum", "Model przestaje wymagać walidacji", "Test staje się zbiorem stratyfikowanym"], correct: [0], explain: "To przeciek danych: wynik laboratoryjny jest zbyt optymistyczny i nie powtarza się po wdrożeniu.", src: "W05, slajd 12", note: "W05-klasyfikacja" },
  { id: "W05-10", w: "W05", c: "baseline", type: "single", q: "Jaki jest najprostszy baseline klasyfikacyjny według wykładu?", options: ["Zawsze przewiduj klasę większości", "Prosty model k-NN z k = 1", "Zawsze przewiduj klasę mniejszości", "Pojedyncze drzewo bez przycinania"], correct: [0], explain: "Najprostszy baseline zawsze zwraca klasę większości.", src: "W05, slajd 13", note: "W05-klasyfikacja" },
  { id: "W05-11", w: "W05", c: "baseline", type: "single", q: "Przy niezrównoważonych klasach baseline „klasa większości” może mieć:", options: ["niskie accuracy i wysoki recall", "wysokie accuracy i zerowy recall", "zerową precision i wysoki recall", "zerowe accuracy i wysoką precision"], correct: [1], explain: "Model zawsze zwracający klasę większości ma wysokie accuracy, ale nie wykrywa klasy pozytywnej.", src: "W05, slajd 13", note: "W05-klasyfikacja" },
  { id: "W05-12", w: "W05", c: "knn-k", type: "single", q: "Jaki jest skutek zbyt małego k w k-NN?", options: ["Model gładszy i stabilniejszy", "Niedouczenie lokalnych zależności", "Przeuczenie i wysoka wariancja", "Brak remisów w głosowaniu"], correct: [2], explain: "Małe k: model bardzo lokalny, czuły na szum, wysoka wariancja, przeuczenie.", src: "W05, slajd 16", note: "W05-klasyfikacja" },
  { id: "W05-32", w: "W05", c: "knn-k", type: "single", q: "Dlaczego w binarnej klasyfikacji k-NN często wybiera się nieparzyste k?", options: ["Aby zmniejszyć koszt liczenia odległości", "Aby ograniczyć remisy w głosowaniu", "Aby uniknąć skalowania cech liczbowych", "Aby model był bardziej lokalny"], correct: [1], explain: "Przy dwóch klasach nieparzyste k ogranicza remisy w głosowaniu sąsiadów.", src: "W05, slajd 16", note: "W05-klasyfikacja" },
  { id: "W05-33", w: "W05", c: "knn-k", type: "single", q: "Jak według wykładu dobiera się wartość k w k-NN?", options: ["Przez walidację, jako hiperparametr", "Na zbiorze testowym, po końcowej ocenie", "Zawsze jako liczbę klas powiększoną o 1", "Razem ze współczynnikami w treningu"], correct: [0], explain: "k to hiperparametr dobierany przez walidację; test służy tylko do końcowej oceny.", src: "W05, slajd 16", note: "W05-klasyfikacja" },
  { id: "W05-13", w: "W05", c: "knn-skalowanie", type: "single", q: "W k-NN bez skalowania cecha „dochód” ma ogromny zakres. Co się dzieje?", options: ["Może zdominować odległość", "Zostaje pominięta przez model", "Zmniejsza wariancję modelu", "Zamienia k-NN w model liniowy"], correct: [0], explain: "Bez skalowania cecha o dużym zakresie może zdominować odległość i zmienić sąsiadów.", src: "W05, slajd 17", note: "W05-klasyfikacja" },
  { id: "W05-34", w: "W05", c: "knn-skalowanie", type: "single", q: "Przed k-NN cechy poddano standaryzacji. Co może się zmienić według wykładu?", options: ["Etykiety obserwacji treningowych", "Najbliżsi sąsiedzi i predykcja", "Liczba klas w zbiorze danych", "Wartość parametru k"], correct: [1], explain: "Standaryzacja lub min–max zmienia odległości, więc może zmienić najbliższych sąsiadów i predykcję.", src: "W05, slajd 17", note: "W05-klasyfikacja" },
  { id: "W05-14", w: "W05", c: "nb-naiwny", type: "single", q: "Dlaczego naiwny Bayes jest nazywany „naiwnym”?", options: ["Zakłada liniową granicę decyzyjną", "Ignoruje prawdopodobieństwo a priori", "Działa tylko dla cech binarnych", "Zakłada niezależność cech przy danej klasie"], correct: [3], explain: "Zakłada niezależność cech warunkowo względem klasy, a w realnych danych cechy są często powiązane.", src: "W05, slajd 20", note: "W05-klasyfikacja" },
  { id: "W05-35", w: "W05", c: "nb-naiwny", type: "single", q: "Który klasyfikator zakłada niezależność cech warunkowo względem klasy?", options: ["k-NN", "Drzewo decyzyjne", "Regresja logistyczna", "Naiwny Bayes"], correct: [3], explain: "Naiwny Bayes upraszcza P(x | C) do iloczynu wpływów cech, zakładając ich niezależność przy danej klasie.", src: "W05, slajd 20", note: "W05-klasyfikacja" },
  { id: "W05-36", w: "W05", c: "nb-naiwny", type: "single", q: "Które stwierdzenie o założeniu naiwnego Bayesa NIE jest zgodne z wykładem?", options: ["Zakłada niezależność cech przy danej klasie", "Jest naiwne, bo cechy często są powiązane", "Upraszcza P(x | C) do iloczynu wpływów cech", "Przez nie model nie nadaje się do tekstu"], correct: [3], explain: "Mimo uproszczenia NB bywa skuteczny, zwłaszcza w klasyfikacji tekstu.", src: "W05, slajd 20", note: "W05-klasyfikacja" },
  { id: "W05-15", w: "W05", c: "nb-warianty", type: "single", q: "Tekst opisano jako bag-of-words z licznościami słów. Który wariant NB pasuje najlepiej?", options: ["Gaussian NB", "Bernoulli NB", "Multinomial NB", "Logistic NB"], correct: [2], explain: "Multinomial NB: liczności lub częstości, szczególnie bag-of-words.", src: "W05, slajd 21", note: "W05-klasyfikacja" },
  { id: "W05-37", w: "W05", c: "nb-warianty", type: "single", q: "Tekst opisano wektorem 0/1: czy dane słowo wystąpiło w wiadomości. Który wariant NB pasuje najlepiej?", options: ["Multinomial NB", "Gaussian NB", "Bernoulli NB", "Logistic NB"], correct: [2], explain: "Bernoulli NB: cechy binarne 0/1, np. czy słowo wystąpiło; Multinomial NB: liczności słów.", src: "W05, slajd 21", note: "W05-klasyfikacja" },
  { id: "W05-38", w: "W05", c: "nb-warianty", type: "single", q: "Klienta opisano cechami ciągłymi: wiek, dochód i czas sesji. Który wariant NB pasuje najlepiej?", options: ["Bernoulli NB", "Gaussian NB", "Multinomial NB", "Logistic NB"], correct: [1], explain: "Gaussian NB stosuje się do cech liczbowych ciągłych, np. wieku, dochodu, czasu sesji.", src: "W05, slajd 21", note: "W05-klasyfikacja" },
  { id: "W05-16", w: "W05", c: "logreg", type: "single", q: "Ile wynosi p = 1 / (1 + e⁻ᶻ) dla wyniku liniowego z = 0?", options: ["0,0", "0,5", "1,0", "2,0"], correct: [1], explain: "Dla z = 0 mamy e⁰ = 1, więc p = 1 / (1 + 1) = 0,5.", src: "W05, slajd 25", note: "W05-klasyfikacja" },
  { id: "W05-17", w: "W05", c: "logreg", type: "single", q: "Czym jest logit według wykładu?", options: ["Funkcją przekształcającą z do przedziału 0–1", "Karą za sumę kwadratów współczynników", "Logarytmem ilorazu szans log(p/(1−p))", "Wynikiem liniowym z = β₀ + β₁x₁ + …"], correct: [2], explain: "Logit to logarytm ilorazu szans; funkcja logistyczna działa odwrotnie i daje wynik 0–1.", src: "W05, slajd 25", note: "W05-klasyfikacja" },
  { id: "W05-18", w: "W05", c: "prog", type: "single", q: "Bank obniża próg decyzyjny w wykrywaniu oszustw. Czego należy się spodziewać?", options: ["Mniej alarmów, więcej pominięć", "Więcej wykrytych i więcej fałszywych alarmów", "Tej samej liczby alarmów co przy 0,5", "Wyższej precision i niższego recall"], correct: [1], explain: "Niski próg: więcej wykrytych przypadków, więcej fałszywych alarmów, wysoki recall.", src: "W05, slajd 27", note: "W05-klasyfikacja" },
  { id: "W05-39", w: "W05", c: "prog", type: "single", q: "Szpital podnosi próg decyzyjny w modelu wykrywania choroby. Czego należy się spodziewać?", options: ["Więcej alarmów i wyższego recall", "Mniej alarmów i więcej pominięć", "Tych samych decyzji co przy 0,5", "Więcej wykrytych chorych pacjentów"], correct: [1], explain: "Wysoki próg: mniej alarmów, wyższa precision, ale większe ryzyko pominięcia przypadku.", src: "W05, slajd 27", note: "W05-klasyfikacja" },
  { id: "W05-40", w: "W05", c: "prog", type: "single", q: "Na jakiej podstawie według wykładu dobiera się próg decyzyjny?", options: ["Uniwersalnej zasady, że próg wynosi 0,5", "Wyniku na teście po końcowej ocenie modelu", "Kosztów FP, FN i możliwości operacyjnych", "Liczby cech i współczynników w modelu"], correct: [2], explain: "Próg dobiera się do kosztów FP i FN oraz możliwości operacyjnych; 0,5 to tylko ustawienie domyślne.", src: "W05, slajd 27", note: "W05-klasyfikacja" },
  { id: "W05-19", w: "W05", c: "regularyzacja", type: "single", q: "Która regularizacja może zerować współczynniki i działać jak selekcja cech?", options: ["L1 / Lasso", "L2 / Ridge", "Post-pruning", "Głosowanie ważone"], correct: [0], explain: "L1 karze sumę wartości bezwzględnych i może zerować współczynniki; L2 stabilizuje model.", src: "W05, slajd 28", note: "W05-klasyfikacja" },
  { id: "W05-41", w: "W05", c: "regularyzacja", type: "single", q: "Za co karze regularyzacja L2 / Ridge?", options: ["Za sumę wartości bezwzględnych współczynników", "Za sumę kwadratów współczynników", "Za liczbę cech o niezerowej wadze", "Za błędy treningowe punktów przy granicy"], correct: [1], explain: "L2 karze sumę kwadratów współczynników; L1 karze sumę wartości bezwzględnych.", src: "W05, slajd 28", note: "W05-klasyfikacja" },
  { id: "W05-42", w: "W05", c: "regularyzacja", type: "single", q: "Model ma wiele silnie skorelowanych cech i trzeba ustabilizować współczynniki. Którą regularyzację wskazuje wykład?", options: ["L1 / Lasso", "L2 / Ridge", "Pre-pruning", "Bagging"], correct: [1], explain: "L2 stabilizuje model, zwłaszcza przy cechach skorelowanych; L1 może zerować współczynniki.", src: "W05, slajd 28", note: "W05-klasyfikacja" },
  { id: "W05-20", w: "W05", c: "drzewo", type: "single", q: "Co w drzewie decyzyjnym oznacza wartość Gini równa 0?", options: ["Maksymalną niepewność klasy", "Brak zysku informacyjnego", "Węzeł zawiera jedną klasę", "Podział na równe proporcje"], correct: [2], explain: "Gini mierzy nieczystość węzła; 0 oznacza jedną klasę.", src: "W05, slajd 31", note: "W05-klasyfikacja" },
  { id: "W05-21", w: "W05", c: "drzewo", type: "single", q: "Który parametr dotyczy pre-pruningu drzewa decyzyjnego?", options: ["learning rate", "max_depth", "gamma", "parametr C"], correct: [1], explain: "Pre-pruning: max_depth, min_samples_leaf, min_samples_split.", src: "W05, slajd 33", note: "W05-klasyfikacja" },
  { id: "W05-22", w: "W05", c: "ensemble", type: "single", q: "Czym Random Forest różni się od zwykłego baggingu drzew?", options: ["Uczy drzewa sekwencyjnie na błędach", "Losuje podzbiór cech przy każdym podziale", "Używa jednego głębokiego drzewa", "Nie stosuje prób bootstrap"], correct: [1], explain: "Random Forest dodaje losowanie podzbioru cech przy każdym podziale.", src: "W05, slajd 36", note: "W05-klasyfikacja" },
  { id: "W05-23", w: "W05", c: "ensemble", type: "single", q: "Które podejście buduje modele sekwencyjnie i poprawia błędy poprzedników?", options: ["Bagging", "Random Forest", "Boosting", "Walidacja krzyżowa"], correct: [2], explain: "Boosting działa sekwencyjnie; bagging buduje modele równolegle i redukuje wariancję.", src: "W05, slajd 35", note: "W05-klasyfikacja" },
  { id: "W05-24", w: "W05", c: "waznosc", type: "single", q: "Permutation importance mierzy:", options: ["jak często cecha poprawiała podziały", "wartość współczynnika po standaryzacji", "spadek jakości po przetasowaniu cechy", "liczbę drzew używających tej cechy"], correct: [2], explain: "Permutation importance: o ile spada jakość po przetasowaniu cechy.", src: "W05, slajd 38", note: "W05-klasyfikacja" },
  { id: "W05-43", w: "W05", c: "waznosc", type: "single", q: "W lesie losowym cecha „liczba reklamacji” ma najwyższą ważność. Co z tego wynika według wykładu?", options: ["Reklamacje są przyczyną odejścia klientów", "To wskazówka interpretacyjna, nie dowód", "Pozostałe cechy można bezpiecznie usunąć", "Model jest wolny od przecieku danych"], correct: [1], explain: "Ważność cech to wskazówka interpretacyjna, a nie dowód przyczynowości.", src: "W05, slajd 38", note: "W05-klasyfikacja" },
  { id: "W05-44", w: "W05", c: "waznosc", type: "single", q: "Która miara ważności cech opiera się na tym, jak często i mocno cecha poprawiała podziały w drzewach?", options: ["Permutation importance", "Impurity-based importance", "Regularyzacja L1 / Lasso", "Współczynniki po standaryzacji"], correct: [1], explain: "Impurity-based: jak często i mocno cecha poprawiała podziały; permutation: spadek jakości po przetasowaniu.", src: "W05, slajd 38", note: "W05-klasyfikacja" },
  { id: "W05-25", w: "W05", c: "svm", type: "single", q: "Czym są wektory nośne w SVM?", options: ["Punktami najbliższymi granicy decyzyjnej", "Cechami tworzonymi przez kernel trick", "Punktami najdalszymi od granicy", "Współczynnikami wyzerowanymi przez L1"], correct: [0], explain: "Wektory nośne to punkty najbliższe granicy, które decydują o jej położeniu.", src: "W05, slajd 39", note: "W05-klasyfikacja" },
  { id: "W05-45", w: "W05", c: "svm", type: "single", q: "Co kontroluje parametr C w SVM?", options: ["Lokalność wpływu punktów w jądrze RBF", "Karę za błędy na danych treningowych", "Liczbę najbliższych sąsiadów", "Szybkość uczenia kolejnych modeli"], correct: [1], explain: "C kontroluje karę za błędy treningowe; gamma w jądrze RBF kontroluje lokalność wpływu punktów.", src: "W05, slajd 39", note: "W05-klasyfikacja" },
  { id: "W05-46", w: "W05", c: "svm", type: "single", q: "Co według wykładu umożliwia kernel trick w SVM?", options: ["Zerowanie współczynników jak selekcja cech", "Wybór punktów najdalszych od granicy", "Nieliniowe granice bez jawnych nowych cech", "Redukcję wariancji dzięki próbom bootstrap"], correct: [2], explain: "Kernel trick pozwala tworzyć nieliniowe granice bez jawnego tworzenia nowych cech.", src: "W05, slajd 39", note: "W05-klasyfikacja" },
]});

// data/W06.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W06-01", w: "W06", c: "pred-vs-klas", type: "single", q: "Czym według wykładu różni się predykcja od klasyfikacji?", options: ["Liczbą cech wejściowych modelu", "Rodzajem zmiennej docelowej", "Sposobem podziału na trening i test", "Wielkością zbioru treningowego"], correct: [1], explain: "Predykcja przewiduje wartość liczbową, klasyfikacja etykietę klasy.", src: "W06, slajd 4", note: "W06-predykcja" },
  { id: "W06-02", w: "W06", c: "pred-vs-klas", type: "single", q: "Który zestaw metryk wykład przypisuje do predykcji (regresji)?", options: ["accuracy, precision, recall", "precision, recall, F1", "MAE, RMSE, R²", "accuracy, F1, R²"], correct: [2], explain: "Dla predykcji: MAE, RMSE, R² i inne; accuracy, precision, recall, F1 są dla klasyfikacji.", src: "W06, slajd 4", note: "W06-predykcja" },
  { id: "W06-03", w: "W06", c: "pred-vs-klas", type: "single", q: "Które zadanie NIE jest zadaniem predykcyjnym w rozumieniu wykładu?", options: ["Prognoza tygodniowej sprzedaży", "Szacowanie czasu dostawy", "Wycena mieszkania w zł", "Wykrycie churn / brak churnu"], correct: [3], explain: "Churn / brak churnu to etykieta klasy, czyli klasyfikacja; w predykcji wynikiem jest liczba.", src: "W06, slajd 4", note: "W06-predykcja" },
  { id: "W06-04", w: "W06", c: "jednostka-horyzont", type: "single", q: "Okres, którego dotyczy przewidywanie, to według wykładu:", options: ["horyzont", "moment prognozy", "jednostka analizy", "zmienna docelowa"], correct: [0], explain: "Horyzont to okres przewidywania; moment prognozy mówi, kiedy model ma zostać użyty.", src: "W06, slajd 7", note: "W06-predykcja" },
  { id: "W06-26", w: "W06", c: "jednostka-horyzont", type: "single", q: "Czym według wykładu jest jednostka analizy w zadaniu predykcyjnym?", options: ["Obiekt, dla którego powstaje jedna prognoza", "Wartość liczbowa, która ma zostać przewidziana", "Okres, którego dotyczy przewidywanie modelu", "Chwila, w której model ma zostać użyty"], correct: [0], explain: "Jednostka analizy to obiekt, dla którego powstaje jedna prognoza. Wartość do przewidzenia to zmienna docelowa.", src: "W06, slajd 7", note: "W06-predykcja" },
  { id: "W06-27", w: "W06", c: "jednostka-horyzont", type: "single", q: "Model sprzedaży ma być uruchamiany w każdy poniedziałek rano. Który element problemu predykcyjnego określa ta informacja?", options: ["horyzont", "moment prognozy", "jednostka analizy", "zmienna docelowa"], correct: [1], explain: "Moment prognozy mówi, kiedy model ma zostać użyty. Horyzont to okres, którego dotyczy przewidywanie.", src: "W06, slajd 8", note: "W06-predykcja" },
  { id: "W06-05", w: "W06", c: "podzial", type: "single", q: "Do czego według wykładu służy zbiór walidacyjny?", options: ["Do dopasowania modelu i transformacji", "Do jednorazowej oceny końcowej", "Do wyboru hiperparametrów modelu", "Do zamrożenia modelu po treningu"], correct: [2], explain: "Walidacja służy do wyboru hiperparametrów i porównania wariantów; test to ocena końcowa.", src: "W06, slajd 9", note: "W06-predykcja" },
  { id: "W06-06", w: "W06", c: "podzial", type: "single", q: "Jednorazowa ocena końcowa po zamrożeniu modelu odbywa się na zbiorze:", options: ["treningowym", "testowym", "walidacyjnym", "całym zbiorze danych"], correct: [1], explain: "Test to jednorazowa ocena końcowa po zamrożeniu modelu.", src: "W06, slajd 9", note: "W06-predykcja" },
  { id: "W06-07", w: "W06", c: "baseline", type: "single", q: "Który baseline wykład zaleca dla szeregów czasowych?", options: ["Mediana z treningu", "Średnia z treningu", "Reguła losowa", "Wartość ostatnia"], correct: [3], explain: "Wartość ostatnia: prognozuj to, co było ostatnio; ma sens w szeregach czasowych.", src: "W06, slajd 10", note: "W06-predykcja" },
  { id: "W06-08", w: "W06", c: "baseline", type: "single", q: "Baseline ma MAE = 18, model A MAE = 23, model B MAE = 11. Jaki wniosek podaje wykład?", options: ["Oba modele wnoszą wartość", "Tylko model A wnosi wartość", "Tylko model B wnosi wartość", "Żaden model nie wnosi wartości"], correct: [2], explain: "Tylko model B ma mniejszy błąd niż baseline; model A jest od niego gorszy.", src: "W06, slajd 11", note: "W06-predykcja" },
  { id: "W06-09", w: "W06", c: "baseline", type: "single", q: "Dane są wrażliwe na outliery. Który baseline ma wtedy sens według wykładu?", options: ["Mediana z treningu", "Średnia z treningu", "Wartość ostatnia", "Reguła sezonowa"], correct: [0], explain: "Mediana ma sens przy wrażliwości na outliery; średnia przy danych względnie stabilnych.", src: "W06, slajd 10", note: "W06-predykcja" },
  { id: "W06-10", w: "W06", c: "przeciek", type: "single", q: "Czy „liczba reklamacji po dostawie” może być cechą modelu czasu dostawy, gdy prognoza powstaje przed dostawą?", options: ["Tak, jeśli jest silnie skorelowana z y", "Tak, jeśli liczona tylko na teście", "Nie, bo jest to cecha kategoryczna", "Nie, bo nie jest znana przy prognozie"], correct: [3], explain: "To informacja z przyszłości, niedostępna w chwili prognozy, czyli przeciek danych.", src: "W06, slajd 12", note: "W06-predykcja" },
  { id: "W06-11", w: "W06", c: "przeciek", type: "multi", q: "Które sytuacje wykład wymienia jako źródła przecieku danych w predykcji?", options: ["Agregaty policzone na całym zbiorze", "Losowy podział czasu mieszający okresy", "Transformacje dopasowane tylko na treningu", "Cechy powstałe po zdarzeniu"], correct: [0, 1, 3], explain: "Dopasowanie transformacji tylko na treningu to zalecenie przeciw przeciekowi, nie jego źródło.", src: "W06, slajd 12", note: "W06-predykcja" },
  { id: "W06-12", w: "W06", c: "pipeline", type: "single", q: "Który krok jest pierwszy w pipeline predykcyjnym z wykładu?", options: ["imputacja", "skalowanie", "podział", "kodowanie"], correct: [2], explain: "Najpierw należy rozdzielić dane, a dopiero potem dopasować transformacje, inaczej łatwo o przeciek.", src: "W06, slajd 13", note: "W06-predykcja" },
  { id: "W06-28", w: "W06", c: "pipeline", type: "single", q: "Imputację i skalowanie dopasowano na całym zbiorze, a dane podzielono dopiero potem. Jakie ryzyko wskazuje wtedy wykład?", options: ["dryf danych", "przeciek danych", "współliniowość cech", "heteroskedastyczność"], correct: [1], explain: "Najpierw należy rozdzielić dane, a dopiero potem dopasować transformacje. Inaczej łatwo o przeciek.", src: "W06, slajd 13", note: "W06-predykcja" },
  { id: "W06-13", w: "W06", c: "reszta", type: "single", q: "Reszta (y − ŷ) jest dodatnia. Co to oznacza według wykładu?", options: ["Model zawyżył wartość", "Model zaniżył wartość", "Model jest przeuczony", "Model jest idealny"], correct: [1], explain: "Reszta dodatnia: y > ŷ, więc model zaniżył wartość.", src: "W06, slajd 19", note: "W06-predykcja" },
  { id: "W06-14", w: "W06", c: "reszta", type: "calc", q: "Cena rzeczywista mieszkania y = 620 000 zł, prognoza ŷ = 600 000 zł. Ile wynosi reszta w zł?", answer: 20000, tolerance: 0, explain: "Reszta = y − ŷ = 620 000 − 600 000 = 20 000 zł; model zaniżył cenę.", src: "W06, slajd 19", note: "W06-predykcja" },
  { id: "W06-15", w: "W06", c: "ols", type: "single", q: "Co minimalizuje metoda najmniejszych kwadratów (OLS)?", options: ["Sumę bezwzględnych reszt", "Sumę kwadratów reszt", "Liczbę cech w modelu", "Średni błąd procentowy"], correct: [1], explain: "OLS minimalizuje Σ (yᵢ − ŷᵢ)²; potęgowanie usuwa znak i mocniej karze duże błędy.", src: "W06, slajd 18", note: "W06-predykcja" },
  { id: "W06-29", w: "W06", c: "ols", type: "single", q: "Które stwierdzenie NIE opisuje metody najmniejszych kwadratów według wykładu?", options: ["Potęgowanie usuwa znak błędu", "Duże błędy są karane mocniej", "Każdy błąd wpływa na wynik liniowo", "Outliery mogą silnie wpływać na model"], correct: [2], explain: "Liniowy wpływ każdego błędu to cecha MAE. OLS podnosi reszty do kwadratu, więc duże błędy i outliery ważą więcej.", src: "W06, slajd 18", note: "W06-predykcja" },
  { id: "W06-16", w: "W06", c: "mse", type: "single", q: "Która miara ma jednostkę równą kwadratowi jednostki y?", options: ["MAE", "RMSE", "MSE", "MAPE"], correct: [2], explain: "Jednostka MSE to kwadrat jednostki y; RMSE i MAE mają jednostkę y.", src: "W06, slajd 22", note: "W06-predykcja" },
  { id: "W06-30", w: "W06", c: "mse", type: "calc", q: "Model popełnił na dwóch obserwacjach błędy 10 i 30. Ile wynosi MSE?", answer: 500, tolerance: 0, explain: "MSE = (10² + 30²) / 2 = (100 + 900) / 2 = 500. Duży błąd dominuje wynik.", src: "W06, slajd 22", note: "W06-predykcja" },
  { id: "W06-17", w: "W06", c: "mae-rmse", type: "single", q: "Pojedyncze wielkie pomyłki są szczególnie kosztowne. Którą miarę preferuje wtedy wykład?", options: ["MAE", "MAPE", "WAPE", "RMSE"], correct: [3], explain: "RMSE silniej karze duże błędy; jest preferowana, gdy wielkie pomyłki są kosztowne.", src: "W06, slajd 24", note: "W06-predykcja" },
  { id: "W06-18", w: "W06", c: "mae-rmse", type: "single", q: "Które stwierdzenie o MAE jest zgodne z wykładem?", options: ["Każdy błąd wpływa na nią liniowo", "Silniej karze duże błędy niż RMSE", "Ma jednostkę kwadratu zmiennej y", "Jest bardziej wrażliwa na outliery"], correct: [0], explain: "W MAE każdy błąd wpływa liniowo; jest odporniejsza na wartości odstające niż RMSE.", src: "W06, slajd 24", note: "W06-predykcja" },
  { id: "W06-19", w: "W06", c: "r2", type: "single", q: "Model ma na teście R² < 0. Co to oznacza według wykładu?", options: ["Model jest idealny, bez błędów", "Model działa jak średnia", "Model gorszy od średniej", "Model ma tylko ujemne reszty"], correct: [2], explain: "R² < 0: model gorszy od predykcji średniej; R² = 0: model jak średnia.", src: "W06, slajd 25", note: "W06-predykcja" },
  { id: "W06-20", w: "W06", c: "r2", type: "single", q: "Która z przyczyn ujemnego R² NIE pada na wykładzie?", options: ["Przeuczenie modelu", "Dryf danych", "Zbyt duży test", "Słabe cechy modelu"], correct: [2], explain: "Wykład wymienia: przeuczenie, dryf, zły podział lub słabe cechy.", src: "W06, slajd 26", note: "W06-predykcja" },
  { id: "W06-21", w: "W06", c: "mape", type: "calc", q: "Wartość rzeczywista y = 1, prognoza ŷ = 3. Ile procent wynosi błąd MAPE dla tej obserwacji?", answer: 200, tolerance: 0.5, explain: "|1 − 3| / 1 = 2, czyli 200%; mały błąd absolutny wygląda katastrofalnie procentowo.", src: "W06, slajd 26", note: "W06-predykcja" },
  { id: "W06-22", w: "W06", c: "mape", type: "single", q: "Dlaczego MAPE jest problematyczne według wykładu?", options: ["Dzieli przez wartość prognozowaną ŷ", "Dzieli przez wartość rzeczywistą y", "Ma jednostkę kwadratu zmiennej y", "Ignoruje kierunek i wielkość błędu"], correct: [1], explain: "MAPE dzieli przez y, więc przy y = 0 jest nieokreślone, a przy małych y może eksplodować.", src: "W06, slajd 26", note: "W06-predykcja" },
  { id: "W06-23", w: "W06", c: "regularyzacja", type: "single", q: "Która regularyzacja może zerować część cech?", options: ["Ridge / L2", "Lasso / L1", "OLS bez kary", "Random Forest"], correct: [1], explain: "Lasso (L1) może zerować część cech; Ridge (L2) zmniejsza współczynniki bez zerowania.", src: "W06, slajd 31", note: "W06-predykcja" },
  { id: "W06-24", w: "W06", c: "regularyzacja", type: "single", q: "Co według wykładu robi Ridge (L2)?", options: ["Łączy selekcję cech i stabilizację wag", "Zeruje część współczynników", "Zmniejsza wagi, ale ich nie zeruje", "Uśrednia wiele drzew regresyjnych"], correct: [2], explain: "Ridge zmniejsza współczynniki, ale ich nie zeruje; łączenie selekcji i stabilizacji to Elastic Net.", src: "W06, slajd 31", note: "W06-predykcja" },
  { id: "W06-25", w: "W06", c: "diagnostyka", type: "single", q: "Na wykresie reszt widać kształt lejka. Na co to wskazuje według wykładu?", options: ["Heteroskedastyczność", "Nieliniowość zależności", "Brak wzorca błędu", "Współliniowość cech"], correct: [0], explain: "Lejek oznacza heteroskedastyczność, łuk nieliniowość, losowy układ wokół zera brak wzorca.", src: "W06, slajd 29", note: "W06-predykcja" },
  { id: "W06-31", w: "W06", c: "diagnostyka", type: "single", q: "Reszty na wykresie układają się w wyraźny łuk. Co to może oznaczać według wykładu?", options: ["Heteroskedastyczność", "Nieliniowość zależności", "Brak prostego wzorca błędu", "Przeuczenie modelu"], correct: [1], explain: "Łuk może oznaczać nieliniowość, a lejek heteroskedastyczność.", src: "W06, slajd 29", note: "W06-predykcja" },
  { id: "W06-32", w: "W06", c: "diagnostyka", type: "single", q: "Które stwierdzenie o analizie reszt NIE jest zgodne z wykładem?", options: ["Losowy układ wokół zera sugeruje brak wzorca błędu", "Analiza reszt zastępuje pojedynczą liczbę metryki", "Lejek na wykresie oznacza heteroskedastyczność", "Łuk na wykresie może oznaczać nieliniowość"], correct: [1], explain: "Analiza reszt uzupełnia pojedynczą liczbę metryki, a nie ją zastępuje.", src: "W06, slajd 29", note: "W06-predykcja" },
]});

// data/W07.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W07-01", w: "W07", c: "klast-def", type: "single", q: "Poszukiwanie grup podobnych obiektów bez znajomości etykiet to:", options: ["klasyfikacja", "klasteryzacja", "selekcja cech", "imputacja braków"], correct: [1], explain: "Klasteryzacja grupuje podobne obiekty bez znanych z góry klas i etykiet.", src: "W07, slajd 3", note: "W07-klasteryzacja" },
  { id: "W07-02", w: "W07", c: "klast-def", type: "single", q: "Co zawierają dane wejściowe w klasteryzacji jako uczeniu nienadzorowanym?", options: ["Macierz cech X i etykietę y", "Tylko etykiety klas y", "Wyłącznie macierz cech X", "Macierz X i wzorcowe klastry"], correct: [2], explain: "Brakuje etykiety y i wzorcowej odpowiedzi; jest tylko macierz cech X.", src: "W07, slajd 4", note: "W07-klasteryzacja" },
  { id: "W07-03", w: "W07", c: "klasyf-vs-klast", type: "single", q: "Który przykład wykład przypisuje do klasteryzacji, a nie do klasyfikacji?", options: ["Klient odejdzie lub nie odejdzie", "Etykieta klasy dla nowego klienta", "Przypisanie nowego klienta do znanej klasy", "Typy klientów o podobnych zachowaniach"], correct: [3], explain: "Klasteryzacja daje segmenty lub profile; klasyfikacja daje etykietę znanej klasy.", src: "W07, slajd 5", note: "W07-klasteryzacja" },
  { id: "W07-26", w: "W07", c: "klasyf-vs-klast", type: "single", q: "Co według wykładu jest wynikiem klasyfikacji?", options: ["Segmenty lub profile obiektów", "Etykieta jednej ze znanych klas", "Techniczne numery klastrów 0, 1, 2", "Dendrogram z kolejnością połączeń"], correct: [1], explain: "Klasyfikacja daje etykietę klasy znanej z danych treningowych; segmenty lub profile to wynik klasteryzacji.", src: "W07, slajd 5", note: "W07-klasteryzacja" },
  { id: "W07-27", w: "W07", c: "klasyf-vs-klast", type: "single", q: "Która cecha dotyczy klasyfikacji, a NIE klasteryzacji?", options: ["Brak z góry zadanych klas", "Algorytm sam szuka grup obiektów", "Znane klasy w danych treningowych", "Wynik w postaci segmentów lub profili"], correct: [2], explain: "Klasyfikacja wymaga znanych klas w danych treningowych; klasteryzacja nie ma z góry zadanych klas.", src: "W07, slajd 5", note: "W07-klasteryzacja" },
  { id: "W07-04", w: "W07", c: "dobry-klaster", type: "single", q: "Cecha dobrego klastra: „podział nie znika po małej zmianie danych” to:", options: ["spójność", "separacja", "stabilność", "użyteczność"], correct: [2], explain: "Stabilność oznacza, że podział nie znika po małej zmianie danych.", src: "W07, slajd 7", note: "W07-klasteryzacja" },
  { id: "W07-05", w: "W07", c: "dobry-klaster", type: "single", q: "Czym jest separacja jako cecha dobrego klastra?", options: ["Klastry są od siebie odróżnialne", "Obiekty w klastrze są podobne", "Profil klastra da się nazwać", "Segment prowadzi do działania"], correct: [0], explain: "Separacja: klastry są odróżnialne; spójność: obiekty wewnątrz są podobne.", src: "W07, slajd 7", note: "W07-klasteryzacja" },
  { id: "W07-06", w: "W07", c: "skalowanie", type: "single", q: "Dlaczego przed k-means standaryzuje się cechy?", options: ["Bo algorytmy odległościowe są wrażliwe na zakres cech", "Bo standaryzacja nadaje wszystkim cechom równą ważność", "Bo bez niej nie da się policzyć centroidów", "Bo standaryzacja usuwa obserwacje odstające"], correct: [0], explain: "Cecha o dużym zakresie, np. dochód w zł, może „przykryć” wiek; porównywalna skala nie oznacza równej ważności.", src: "W07, slajd 12", note: "W07-klasteryzacja" },
  { id: "W07-07", w: "W07", c: "skalowanie", type: "single", q: "Cecha ma średnią μ = 50 i odchylenie standardowe σ = 10. Ile wynosi z dla x = 70?", options: ["7", "20", "2", "0,5"], correct: [2], explain: "z = (x − μ) / σ = (70 − 50) / 10 = 2, czyli 2 odchylenia standardowe od średniej.", src: "W07, slajd 12", note: "W07-klasteryzacja" },
  { id: "W07-08", w: "W07", c: "one-hot", type: "single", q: "Jaki problem wprowadza zakodowanie kategorii jako 1, 2, 3?", options: ["Zwiększa rzadkość danych", "Może wprowadzić fałszywy porządek", "Tworzy osobną kolumnę binarną dla kategorii", "Zwiększa wymiar danych"], correct: [1], explain: "Kategorie nie mają naturalnej odległości liczbowej; rzadkość i wzrost wymiaru to skutki one-hot.", src: "W07, slajd 13", note: "W07-klasteryzacja" },
  { id: "W07-28", w: "W07", c: "one-hot", type: "single", q: "Na czym polega one-hot encoding?", options: ["Zastępuje kategorie kolejnymi liczbami 1, 2, 3", "Tworzy osobną kolumnę binarną dla każdej kategorii", "Łączy cechy liczbowe i kategoryczne w jednej mierze", "Przelicza wartości na liczbę odchyleń od średniej"], correct: [1], explain: "One-hot tworzy osobną kolumnę binarną dla każdej kategorii, więc rośnie wymiar danych.", src: "W07, slajd 13", note: "W07-klasteryzacja" },
  { id: "W07-29", w: "W07", c: "one-hot", type: "single", q: "Jakie ryzyko wykład wiąże z one-hot przy dużej liczbie kategorii?", options: ["Fałszywy porządek między kategoriami", "Zwiększenie rzadkości danych", "Utrata zmiennych oryginalnych", "Przesunięcie centroidów klastrów"], correct: [1], explain: "Duża liczba kategorii może zwiększyć rzadkość danych; fałszywy porządek to problem kodowania 1, 2, 3.", src: "W07, slajd 13", note: "W07-klasteryzacja" },
  { id: "W07-09", w: "W07", c: "outliery", type: "single", q: "Co według wykładu należy zrobić z obserwacjami odstającymi?", options: ["Usunąć je automatycznie przed grupowaniem", "Zastąpić je średnią wartością cechy", "Najpierw określić ich znaczenie", "Zawsze utworzyć z nich osobny klaster"], correct: [2], explain: "Outlierów nie należy usuwać automatycznie; najpierw trzeba określić ich znaczenie.", src: "W07, slajd 14", note: "W07-klasteryzacja" },
  { id: "W07-30", w: "W07", c: "outliery", type: "single", q: "Dlaczego centroid w k-means reaguje na outliery?", options: ["Bo jest medianą punktów klastra", "Bo zawsze jest rzeczywistą obserwacją", "Bo jest średnią punktów klastra", "Bo zależy od promienia eps"], correct: [2], explain: "Centroid jest średnią, więc skrajny punkt może go przesunąć. Centroid nie musi być rzeczywistą obserwacją.", src: "W07, slajd 25", note: "W07-klasteryzacja" },
  { id: "W07-31", w: "W07", c: "outliery", type: "single", q: "W danych są obserwacje odstające. Jaki skutek dla k-means opisuje wykład?", options: ["Zostają automatycznie pominięte przy liczeniu centroidów", "Mogą przesunąć centroid lub utworzyć sztuczny klaster", "Zmniejszają odległości między obiektami w klastrze", "Obniżają wymiar danych i zwiększają ich rzadkość"], correct: [1], explain: "Centroid jest średnią, więc outliery mogą go przesunąć lub utworzyć sztuczny klaster. Odległości przez nie rosną, a nie maleją.", src: "W07, slajd 25", note: "W07-klasteryzacja" },
  { id: "W07-10", w: "W07", c: "miary-odl", type: "single", q: "Którą miarę wykład wskazuje jako najlepszą dla tekstu i wektorów rzadkich?", options: ["Jaccarda", "Gowera", "euklidesową", "cosinusową"], correct: [3], explain: "Cosinusowa porównuje kierunek, a nie długość wektora.", src: "W07, slajd 15", note: "W07-klasteryzacja" },
  { id: "W07-11", w: "W07", c: "miary-odl", type: "single", q: "Zbiór zawiera jednocześnie cechy liczbowe i kategoryczne. Jaka miara pasuje według wykładu?", options: ["Gowera", "euklidesowa", "Jaccarda", "cosinusowa"], correct: [0], explain: "Odległość Gowera łączy cechy liczbowe i kategoryczne.", src: "W07, slajd 15", note: "W07-klasteryzacja" },
  { id: "W07-12", w: "W07", c: "pca-selekcja", type: "single", q: "Czym PCA różni się od selekcji cech według wykładu?", options: ["Zachowuje wybrane zmienne oryginalne", "Tworzy nowe składowe maksymalizujące wariancję", "Usuwa obserwacje odstające przed redukcją wymiaru", "Koduje kategorie w kolumny binarne"], correct: [1], explain: "PCA tworzy nowe składowe; selekcja cech zachowuje wybrane zmienne oryginalne.", src: "W07, slajd 16", note: "W07-klasteryzacja" },
  { id: "W07-32", w: "W07", c: "pca-selekcja", type: "single", q: "Analityk chce zmniejszyć liczbę wymiarów i zostawić część zmiennych w oryginalnej postaci. Co wybrać według wykładu?", options: ["PCA", "Selekcję cech", "One-hot encoding", "Standaryzację cech"], correct: [1], explain: "Selekcja cech zachowuje wybrane zmienne oryginalne; PCA tworzy nowe składowe.", src: "W07, slajd 16", note: "W07-klasteryzacja" },
  { id: "W07-33", w: "W07", c: "pca-selekcja", type: "single", q: "Nowe składowe maksymalizujące wariancję tworzy według wykładu:", options: ["selekcja cech", "one-hot encoding", "PCA", "metoda Warda"], correct: [2], explain: "PCA tworzy nowe składowe maksymalizujące wariancję; selekcja cech zostawia oryginalne zmienne.", src: "W07, slajd 16", note: "W07-klasteryzacja" },
  { id: "W07-13", w: "W07", c: "kmeans-kroki", type: "single", q: "Jaka jest kolejność kroków k-means?", options: ["Zainicjalizuj centroidy, wybierz k, przypisz punkty, powtarzaj", "Wybierz k, przypisz punkty, zainicjalizuj centroidy, powtarzaj", "Wybierz k, zainicjalizuj centroidy, przypisz punkty, zaktualizuj", "Przypisz punkty, wybierz k, zaktualizuj centroidy, powtarzaj"], correct: [2], explain: "Wybierz k, zainicjalizuj centroidy, przypisz punkty, zaktualizuj centroidy, powtarzaj do zbieżności.", src: "W07, slajd 17", note: "W07-klasteryzacja" },
  { id: "W07-34", w: "W07", c: "kmeans-kroki", type: "single", q: "Które dwa kroki k-means powtarza aż do zbieżności?", options: ["Wybór k i inicjalizację centroidów", "Przypisanie punktów i aktualizację centroidów", "Inicjalizację centroidów i przypisanie punktów", "Wybór k i aktualizację centroidów"], correct: [1], explain: "Algorytm naprzemiennie przypisuje punkty do najbliższego centroidu i aktualizuje centroidy. Wybór k i inicjalizacja są tylko na starcie.", src: "W07, slajd 21", note: "W07-klasteryzacja" },
  { id: "W07-35", w: "W07", c: "kmeans-kroki", type: "single", q: "Kiedy k-means kończy powtarzanie kroków?", options: ["Po wykonaniu n_init iteracji", "Gdy WCSS spadnie do zera", "Po jednorazowym przypisaniu punktów", "Gdy algorytm osiągnie zbieżność"], correct: [3], explain: "Kroki powtarza się do zbieżności. n_init to liczba inicjalizacji, nie iteracji.", src: "W07, slajd 17", note: "W07-klasteryzacja" },
  { id: "W07-14", w: "W07", c: "wcss", type: "single", q: "Co dzieje się z WCSS, gdy rośnie liczba klastrów k?", options: ["Maleje", "Rośnie", "Nie zmienia się", "Najpierw rośnie, potem maleje"], correct: [0], explain: "WCSS maleje przy wzroście k, dlatego nie wybiera się k po samym minimum WCSS.", src: "W07, slajd 20", note: "W07-klasteryzacja" },
  { id: "W07-15", w: "W07", c: "wcss", type: "single", q: "Funkcja celu k-means mierząca zwartość klastrów to:", options: ["silhouette score", "WCSS", "indeks Davies–Bouldin", "odległość Gowera"], correct: [1], explain: "WCSS to suma kwadratów odległości punktów od centroidów; jest używana w metodzie łokcia.", src: "W07, slajd 20", note: "W07-klasteryzacja" },
  { id: "W07-16", w: "W07", c: "kmeans-init", type: "single", q: "Do czego służy parametr n_init w k-means?", options: ["Ustala liczbę klastrów k", "Ustala promień sąsiedztwa", "Kontroluje liczbę inicjalizacji", "Wybiera bardziej rozproszone centroidy startowe"], correct: [2], explain: "n_init to liczba startów; wybiera się wynik o najniższym WCSS. Rozproszone centroidy wybiera k-means++.", src: "W07, slajd 24", note: "W07-klasteryzacja" },
  { id: "W07-17", w: "W07", c: "kmeans-init", type: "single", q: "Czym jest k-means++ według wykładu?", options: ["Metodą wyboru bardziej rozproszonych centroidów", "Wersją k-means gwarantującą minimum globalne", "Metodą doboru k na podstawie WCSS", "Wersją k-means dla danych kategorycznych"], correct: [0], explain: "k-means++ nie gwarantuje ideału, ale zwykle poprawia stabilność startu.", src: "W07, slajd 23", note: "W07-klasteryzacja" },
  { id: "W07-18", w: "W07", c: "kmeans-ogr", type: "multi", q: "Które ograniczenia k-means wymienia wykład?", options: ["Wymaga podania k przed startem", "Jest wrażliwy na skalę cech i outliery", "Działa wolno dla dużych zbiorów", "Słabo radzi sobie z nieregularnym kształtem"], correct: [0, 1, 3], explain: "Szybkość dla dużych zbiorów to zaleta k-means, nie ograniczenie.", src: "W07, slajd 26", note: "W07-klasteryzacja" },
  { id: "W07-36", w: "W07", c: "kmeans-ogr", type: "single", q: "Co NIE jest ograniczeniem k-means według wykładu?", options: ["Zależność od inicjalizacji", "Konieczność podania k przed startem", "Wrażliwość na skalę cech i outliery", "Centroidy jako typowe profile grup"], correct: [3], explain: "Centroidy reprezentujące typowe profile grup to zaleta k-means; pozostałe odpowiedzi to ograniczenia.", src: "W07, slajd 26", note: "W07-klasteryzacja" },
  { id: "W07-37", w: "W07", c: "kmeans-ogr", type: "single", q: "Dane tworzą wydłużone grupy o różnej gęstości. Dlaczego k-means może dać słaby wynik?", options: ["Działa najlepiej dla danych kategorycznych", "Preferuje grupy zwarte o podobnej skali", "Łączy grupy według najbliższej pary punktów", "Traktuje klastry jako obszary wysokiej gęstości"], correct: [1], explain: "k-means preferuje klastry zwarte o podobnej skali i słabo radzi sobie z kształtami wydłużonymi oraz różną gęstością.", src: "W07, slajd 25", note: "W07-klasteryzacja" },
  { id: "W07-19", w: "W07", c: "hierarchiczne", type: "single", q: "Jak w klasteryzacji hierarchicznej wybiera się liczbę klastrów?", options: ["Przez podanie k przed startem", "Przez „cięcie” dendrogramu na wysokości", "Przez dobór parametru eps", "Przez najniższe WCSS z wielu uruchomień algorytmu"], correct: [1], explain: "Dendrogram tnie się na wybranej wysokości; im wyżej łączą się gałęzie, tym mniej podobne grupy.", src: "W07, slajd 27", note: "W07-klasteryzacja" },
  { id: "W07-20", w: "W07", c: "hierarchiczne", type: "single", q: "Podejście aglomeracyjne w klasteryzacji hierarchicznej:", options: ["startuje od jednego klastra i go dzieli", "jest mniej popularne niż deglomeracyjne", "działa od ogółu do szczegółu", "startuje od obiektów jako osobnych klastrów"], correct: [3], explain: "Aglomeracyjne łączy najbardziej podobne grupy, od szczegółu do ogółu; to najczęstsza wersja.", src: "W07, slajd 28", note: "W07-klasteryzacja" },
  { id: "W07-21", w: "W07", c: "linkage", type: "single", q: "Która metoda linkage mierzy odległość najbliższej pary punktów i grozi łańcuchowaniem?", options: ["Complete linkage", "Average linkage", "Single linkage", "Metoda Warda"], correct: [2], explain: "Single: najbliższa para i ryzyko łańcuchowania; complete: najdalsza para i zwarte klastry.", src: "W07, slajd 29", note: "W07-klasteryzacja" },
  { id: "W07-22", w: "W07", c: "linkage", type: "single", q: "Metoda Warda łączy klastry według:", options: ["najdalszej pary punktów", "wzrostu wariancji wewnątrz klastrów", "średniej odległości między punktami grup", "najbliższej pary punktów"], correct: [1], explain: "Ward patrzy na wzrost wariancji wewnątrz klastrów i często daje zwarte, zbalansowane grupy.", src: "W07, slajd 29", note: "W07-klasteryzacja" },
  { id: "W07-23", w: "W07", c: "dbscan", type: "single", q: "Co w DBSCAN wyznacza parametr eps?", options: ["Promień lokalnego sąsiedztwa", "Minimalną liczbę punktów rdzenia", "Liczbę klastrów do znalezienia", "Liczbę inicjalizacji algorytmu"], correct: [0], explain: "eps to promień sąsiedztwa; min_samples to minimalna liczba punktów w sąsiedztwie.", src: "W07, slajd 30", note: "W07-klasteryzacja" },
  { id: "W07-24", w: "W07", c: "dbscan", type: "single", q: "Punkt leży w promieniu eps punktu rdzeniowego, ale sam nie ma min_samples sąsiadów. To punkt:", options: ["rdzeniowy", "szumu", "centroidu", "brzegowy"], correct: [3], explain: "Punkt brzegowy dołącza do rdzenia; szum nie leży w zasięgu eps żadnego punktu rdzeniowego.", src: "W07, slajd 30", note: "W07-klasteryzacja" },
  { id: "W07-25", w: "W07", c: "ocena", type: "single", q: "Której miary NIE wymieniono na wykładzie jako miary oceny klasteryzacji?", options: ["Silhouette", "Calinski–Harabasz", "Precision", "Davies–Bouldin"], correct: [2], explain: "Wykład wymienia silhouette, elbow, Calinski–Harabasz i Davies–Bouldin.", src: "W07, slajd 31", note: "W07-klasteryzacja" },
  { id: "W07-38", w: "W07", c: "ocena", type: "single", q: "Silhouette, elbow, Calinski–Harabasz i Davies–Bouldin to według wykładu:", options: ["metody linkage w klasteryzacji hierarchicznej", "miary oceny jakości klasteryzacji", "miary odległości między obiektami", "metody inicjalizacji centroidów k-means"], correct: [1], explain: "To miary oceny jakości klasteryzacji. Metody linkage to single, complete, average i Ward.", src: "W07, slajd 31", note: "W07-klasteryzacja" },
  { id: "W07-39", w: "W07", c: "ocena", type: "single", q: "Co według wykładu obejmuje ocena jakości klasteryzacji?", options: ["Wybór k, inicjalizację i aktualizację centroidów", "Spójność wewnętrzną, separację i stabilność", "Skalowanie, kodowanie i imputację braków", "Dobór eps, min_samples i punktów rdzeniowych"], correct: [1], explain: "Ocena jakości obejmuje spójność wewnętrzną, separację i stabilność rozwiązania.", src: "W07, slajd 31", note: "W07-klasteryzacja" },
]});

// data/W08.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W08-01", w: "W08", c: "asocjacje-def", type: "single", q: "Odkrywanie elementów, które pojawiają się razem częściej, niż oczekiwalibyśmy przypadkowo, to:", options: ["klasyfikacja nadzorowana", "analiza asocjacyjna", "regresja", "redukcja wymiarowości"], correct: [1], explain: "Analiza asocjacyjna odkrywa współwystępowanie elementów lub zdarzeń.", src: "W08, slajd 3", note: "W08-reguly-asocjacyjne" },
  { id: "W08-02", w: "W08", c: "asocjacje-def", type: "single", q: "Dlaczego analiza asocjacyjna jest zaliczana do uczenia nienadzorowanego?", options: ["Bo potwierdza jedną z góry zadaną hipotezę", "Bo przewiduje wartość liczbową zmiennej", "Bo nie ma zmiennej docelowej do przewidywania", "Bo wymaga etykiety klasy dla każdej transakcji"], correct: [2], explain: "Brak zmiennej docelowej; algorytm sam szuka regularności we współwystępowaniu.", src: "W08, slajd 4", note: "W08-reguly-asocjacyjne" },
  { id: "W08-03", w: "W08", c: "od-danych-do-regul", type: "single", q: "Jaka jest kolejność etapów „od danych do reguł” z wykładu?", options: ["transakcje → itemsety → wzorce częste → reguły → decyzje", "itemsety → transakcje → reguły → wzorce częste → decyzje", "transakcje → reguły → itemsety → wzorce częste → decyzje", "wzorce częste → transakcje → itemsety → reguły → decyzje"], correct: [0], explain: "Najpierw transakcje i itemsety, potem wzorce częste, z nich reguły, a na końcu decyzje.", src: "W08, slajd 5", note: "W08-reguly-asocjacyjne" },
  { id: "W08-26", w: "W08", c: "od-danych-do-regul", type: "single", q: "Między którymi etapami ścieżki „od danych do reguł” znajdują się wzorce częste?", options: ["między transakcjami a itemsetami", "między itemsetami a regułami", "po decyzjach, na końcu ścieżki", "między regułami a decyzjami"], correct: [1], explain: "Kolejność: transakcje → itemsety → wzorce częste → reguły → decyzje.", src: "W08, slajd 5", note: "W08-reguly-asocjacyjne" },
  { id: "W08-04", w: "W08", c: "pojecia-wejsciowe", type: "single", q: "Podzbiór elementów, które wystąpiły razem (np. {chleb, masło}), to:", options: ["baza transakcyjna", "zbiór elementów", "pokrycie itemsetu", "transakcja"], correct: [3], explain: "Transakcja to podzbiór elementów, które wystąpiły razem; baza to zbiór wszystkich transakcji.", src: "W08, slajd 7", note: "W08-reguly-asocjacyjne" },
  { id: "W08-27", w: "W08", c: "pojecia-wejsciowe", type: "single", q: "W analizie sklepu wszystkie paragony z badanego okresu to przykład:", options: ["zbioru wszystkich elementów", "pojedynczej transakcji", "bazy transakcyjnej", "pokrycia itemsetu"], correct: [2], explain: "Baza transakcyjna to zbiór wszystkich analizowanych transakcji, np. wszystkie paragony z badanego okresu.", src: "W08, slajd 7", note: "W08-reguly-asocjacyjne" },
  { id: "W08-28", w: "W08", c: "pojecia-wejsciowe", type: "single", q: "Którego pojęcia NIE ma wśród trzech podstawowych pojęć wejściowych z wykładu?", options: ["zbiór elementów", "itemset", "transakcja", "baza transakcyjna"], correct: [1], explain: "Pojęcia wejściowe to zbiór elementów, transakcja i baza transakcyjna; itemsety definiuje się dopiero na nich.", src: "W08, slajd 7", note: "W08-reguly-asocjacyjne" },
  { id: "W08-05", w: "W08", c: "jednostka-analizy", type: "single", q: "Analizowane są zachowania użytkownika w sieci. Jaką jednostkę analizy wskazuje wykład?", options: ["paragon", "pacjent", "sesja", "klient"], correct: [2], explain: "Sesja jest jednostką, gdy analizowane są zachowania użytkownika w sieci.", src: "W08, slajd 8", note: "W08-reguly-asocjacyjne" },
  { id: "W08-06", w: "W08", c: "jednostka-analizy", type: "single", q: "Co według wykładu wynika ze zmiany jednostki analizy (np. z paragonu na klienta)?", options: ["Reguły pozostają takie same", "Rośnie tylko wartość lift", "Maleje rzadkość danych do zera", "Reguły mogą się całkowicie zmienić"], correct: [3], explain: "Zmiana jednostki analizy może całkowicie zmienić otrzymane reguły.", src: "W08, slajd 8", note: "W08-reguly-asocjacyjne" },
  { id: "W08-07", w: "W08", c: "itemset", type: "single", q: "Które stwierdzenie o itemsetach jest zgodne z wykładem?", options: ["{chleb, masło} i {masło, chleb} to różne wzorce", "k-itemset zawiera co najwyżej k elementów", "Kolejność elementów w itemsecie nie ma znaczenia", "Itemset musi zawierać co najmniej dwa elementy"], correct: [2], explain: "Kolejność nie ma znaczenia; k-itemset ma dokładnie k elementów; 1-itemset ma jeden element.", src: "W08, slajd 9", note: "W08-reguly-asocjacyjne" },
  { id: "W08-29", w: "W08", c: "itemset", type: "single", q: "Który z poniższych itemsetów jest 2-itemsetem?", options: ["{chleb}", "{mleko, masło}", "{chleb, masło, mleko}", "{ser, chleb, masło}"], correct: [1], explain: "k-itemset zawiera dokładnie k elementów; {mleko, masło} ma dwa elementy.", src: "W08, slajd 9", note: "W08-reguly-asocjacyjne" },
  { id: "W08-08", w: "W08", c: "pokrycie", type: "single", q: "Czym jest pokrycie itemsetu?", options: ["Zbiorem transakcji zawierających wszystkie jego elementy", "Liczbą elementów należących do itemsetu", "Zbiorem wszystkich podzbiorów tego itemsetu", "Udziałem itemsetu we wszystkich regułach"], correct: [0], explain: "Pokrycie to zbiór transakcji zawierających wszystkie elementy itemsetu.", src: "W08, slajd 13", note: "W08-reguly-asocjacyjne" },
  { id: "W08-09", w: "W08", c: "pokrycie", type: "single", q: "Baza: T1 {chleb, mleko}, T2 {chleb, masło}, T3 {mleko, masło}, T4 {chleb, masło, mleko}, T5 {chleb, masło}. Pokrycie {chleb, masło} to:", options: ["T1, T2, T4, T5", "T2, T4, T5", "T2, T3, T4, T5", "T1, T3, T4"], correct: [1], explain: "Chleb i masło jednocześnie występują w T2, T4 i T5.", src: "W08, slajd 13", note: "W08-reguly-asocjacyjne" },
  { id: "W08-10", w: "W08", c: "support", type: "single", q: "Udział transakcji zawierających wzorzec w całej bazie to:", options: ["support względny", "support bezwzględny", "confidence reguły", "pokrycie itemsetu"], correct: [0], explain: "Support bezwzględny to liczba transakcji, a względny to ich udział w bazie.", src: "W08, slajd 15", note: "W08-reguly-asocjacyjne" },
  { id: "W08-11", w: "W08", c: "support", type: "calc", q: "Na bazie z wykładu (5 transakcji) mleko występuje w T1, T3 i T4. Oblicz support({mleko}).", answer: 0.6, tolerance: 0.01, explain: "support = 3 / 5 = 0,60.", src: "W08, slajd 17", note: "W08-reguly-asocjacyjne" },
  { id: "W08-12", w: "W08", c: "min-support", type: "single", q: "Co powoduje ustawienie zbyt niskiego progu min_support?", options: ["Usunięcie wielu ciekawych wzorców", "Eksplozję liczby kandydatów", "Spadek wartości confidence", "Wzrost wartości lift do 1"], correct: [1], explain: "Zbyt niski próg daje eksplozję liczby kandydatów i duży koszt obliczeń.", src: "W08, slajd 16", note: "W08-reguly-asocjacyjne" },
  { id: "W08-13", w: "W08", c: "min-support", type: "single", q: "Które stwierdzenie o min_support jest zgodne z wykładem?", options: ["Istnieje jedna uniwersalna wartość progu", "Wzorzec o niskim supporcie nie ma znaczenia", "Wysoki próg zwiększa liczbę kandydatów", "Próg często dobiera się iteracyjnie"], correct: [3], explain: "Nie ma uniwersalnej wartości; próg dobiera się iteracyjnie, porównując liczbę i sens reguł.", src: "W08, slajd 16", note: "W08-reguly-asocjacyjne" },
  { id: "W08-14", w: "W08", c: "eksplozja", type: "calc", q: "Ile niepustych itemsetów można utworzyć z 10 elementów?", answer: 1023, tolerance: 0, explain: "Liczba niepustych itemsetów to 2^n − 1, czyli 2^10 − 1 = 1023.", src: "W08, slajd 19", note: "W08-reguly-asocjacyjne" },
  { id: "W08-30", w: "W08", c: "eksplozja", type: "calc", q: "Ile niepustych itemsetów można utworzyć z 6 elementów?", answer: 63, tolerance: 0, explain: "2^n − 1 = 2^6 − 1 = 64 − 1 = 63.", src: "W08, slajd 19", note: "W08-reguly-asocjacyjne" },
  { id: "W08-31", w: "W08", c: "eksplozja", type: "single", q: "Jak według wykładu rośnie liczba możliwych itemsetów wraz z liczbą elementów?", options: ["liniowo", "logarytmicznie", "wykładniczo", "kwadratowo"], correct: [2], explain: "Liczba niepustych itemsetów to 2^n − 1, więc rośnie wykładniczo.", src: "W08, slajd 19", note: "W08-reguly-asocjacyjne" },
  { id: "W08-15", w: "W08", c: "regula-kierunek", type: "single", q: "Jak nazywa się lewa strona reguły X → Y?", options: ["następnik (consequent)", "pokrycie reguły", "wspólny itemset", "poprzednik (antecedent)"], correct: [3], explain: "X to poprzednik (warunek po lewej), Y to następnik (wynik po prawej).", src: "W08, slajd 21", note: "W08-reguly-asocjacyjne" },
  { id: "W08-16", w: "W08", c: "regula-kierunek", type: "single", q: "Co wykład mówi o regułach X → Y i Y → X?", options: ["Mają zawsze identyczne confidence", "Zwykle mają różne confidence", "Mają zawsze różny support", "Opisują to samo pytanie analityczne"], correct: [1], explain: "X → Y i Y → X mają zwykle różne confidence i inne znaczenie; support reguły to support X ∪ Y.", src: "W08, slajd 21", note: "W08-reguly-asocjacyjne" },
  { id: "W08-17", w: "W08", c: "confidence", type: "single", q: "Która miara odpowiada na pytanie „jak wiarygodnie?” i przybliża P(Y | X)?", options: ["confidence", "support reguły", "lift", "leverage"], correct: [0], explain: "Support odpowiada na „jak często?”, a confidence na „jak wiarygodnie?”.", src: "W08, slajd 22", note: "W08-reguly-asocjacyjne" },
  { id: "W08-18", w: "W08", c: "confidence", type: "calc", q: "support(chleb, masło) = 0,60, support(chleb) = 0,80, support(masło) = 0,80. Oblicz confidence(chleb → masło).", answer: 0.75, tolerance: 0.01, explain: "confidence = support(X ∪ Y) / support(X) = 0,60 / 0,80 = 0,75.", src: "W08, slajd 24", note: "W08-reguly-asocjacyjne" },
  { id: "W08-19", w: "W08", c: "confidence", type: "single", q: "Reguła chleb → masło ma confidence 0,75, a masło występuje w 80% transakcji. Jaki wniosek wyciąga wykład?", options: ["Reguła jest silna, bo confidence > 0,5", "Wysokie confidence wynika z popularności masła", "Reguła jest nieważna, bo support < 1", "Leverage tej reguły musi być dodatni"], correct: [1], explain: "Wysokie confidence może wynikać z popularności następnika; dlatego potrzebny jest lift.", src: "W08, slajd 24", note: "W08-reguly-asocjacyjne" },
  { id: "W08-20", w: "W08", c: "lift", type: "single", q: "Jak oblicza się lift(X → Y)?", options: ["support(X ∪ Y) / support(X)", "support(X ∪ Y) − support(X)·support(Y)", "confidence(X → Y) / support(Y)", "confidence(X → Y) / support(X)"], correct: [2], explain: "Lift porównuje confidence z częstością bazową następnika Y.", src: "W08, slajd 25", note: "W08-reguly-asocjacyjne" },
  { id: "W08-21", w: "W08", c: "lift", type: "single", q: "Reguła ma lift = 1. Co to oznacza według wykładu?", options: ["Silną zależność dodatnią", "Współwystępowanie rzadsze od oczekiwanego", "Confidence równe 100%", "Brak dodatkowej zależności ponad bazę"], correct: [3], explain: "Lift = 1: brak zależności; lift > 1: dodatnia; lift < 1: rzadsze od oczekiwanego.", src: "W08, slajd 25", note: "W08-reguly-asocjacyjne" },
  { id: "W08-22", w: "W08", c: "lift", type: "calc", q: "confidence(chleb → masło) = 0,75, support(masło) = 0,80. Oblicz lift(chleb → masło) (2 miejsca po przecinku).", answer: 0.94, tolerance: 0.01, explain: "lift = 0,75 / 0,80 ≈ 0,94 < 1, więc reguła jest słabsza od oczekiwanej bazy.", src: "W08, slajd 28", note: "W08-reguly-asocjacyjne" },
  { id: "W08-23", w: "W08", c: "leverage", type: "single", q: "Leverage reguły jest ujemne. Jak to interpretuje wykład?", options: ["Współwystępowanie rzadsze od oczekiwanego", "Zależność dodatnia między X i Y", "Zależność słaba, bliska zeru", "Błąd obliczeń, leverage jest zawsze ≥ 0"], correct: [0], explain: "Leverage = support(X ∪ Y) − support(X)·support(Y); wartość ujemna oznacza rzadsze współwystępowanie.", src: "W08, slajd 26", note: "W08-reguly-asocjacyjne" },
  { id: "W08-32", w: "W08", c: "leverage", type: "single", q: "Która miara mierzy bezwzględną różnicę między częstością rzeczywistą i oczekiwaną?", options: ["lift", "confidence", "leverage", "support"], correct: [2], explain: "Leverage = support(X ∪ Y) − support(X) × support(Y), czyli różnica, a nie iloraz jak lift.", src: "W08, slajd 26", note: "W08-reguly-asocjacyjne" },
  { id: "W08-33", w: "W08", c: "leverage", type: "calc", q: "support(X ∪ Y) = 0,30, support(X) = 0,50, support(Y) = 0,40. Oblicz leverage(X → Y).", answer: 0.1, tolerance: 0.01, explain: "leverage = 0,30 − 0,50 × 0,40 = 0,30 − 0,20 = 0,10; wartość dodatnia oznacza zależność dodatnią.", src: "W08, slajd 26", note: "W08-reguly-asocjacyjne" },
  { id: "W08-24", w: "W08", c: "apriori", type: "single", q: "Itemset {chleb, ser} nie spełnia min_support. Co wynika z własności antymonotonicznej?", options: ["{chleb} też nie spełnia min_support", "{chleb, ser, masło} może być częsty", "{chleb, ser, masło} nie może być częsty", "Trzeba ponownie policzyć support {ser}"], correct: [2], explain: "Jeśli itemset nie jest częsty, to żaden jego nadzbiór nie może być częsty.", src: "W08, slajd 29", note: "W08-reguly-asocjacyjne" },
  { id: "W08-34", w: "W08", c: "apriori", type: "single", q: "Zasada, że każdy podzbiór częstego itemsetu też musi być częsty, to:", options: ["własność antymonotoniczna", "rzadkość danych transakcyjnych", "eksplozja kombinatoryczna", "pokrycie częstego itemsetu"], correct: [0], explain: "Własność antymonotoniczna: podzbiory częstego itemsetu są częste, a nadzbiory rzadkiego są rzadkie.", src: "W08, slajd 29", note: "W08-reguly-asocjacyjne" },
  { id: "W08-35", w: "W08", c: "apriori", type: "single", q: "Do czego Apriori wykorzystuje własność antymonotoniczną?", options: ["Do kompresji bazy we wspólnym drzewie", "Do wyboru kierunku reguły X → Y", "Do odcinania kandydatów na wczesnych etapach", "Do porównania confidence z częstością bazową"], correct: [2], explain: "Rzadki itemset wyklucza wszystkie swoje nadzbiory, więc wielu kandydatów odpada już na wczesnych etapach.", src: "W08, slajd 29", note: "W08-reguly-asocjacyjne" },
  { id: "W08-25", w: "W08", c: "apriori-vs-fp", type: "single", q: "Czym FP-Growth różni się od Apriori według wykładu?", options: ["Generuje kandydatów poziomami: L1, C2, L2", "Wymaga wielu przebiegów po bazie", "Działa tylko przy wysokim min_support", "Kompresuje bazę w drzewo prefiksowe"], correct: [3], explain: "FP-Growth wstawia transakcje do FP-tree i unika jawnego generowania wszystkich kandydatów.", src: "W08, slajd 31", note: "W08-reguly-asocjacyjne" },
  { id: "W08-36", w: "W08", c: "apriori-vs-fp", type: "single", q: "Co NIE jest ograniczeniem algorytmu Apriori wymienionym na wykładzie?", options: ["wiele przebiegów po bazie transakcyjnej", "duża liczba kandydatów przy niskim min_support", "kompresja transakcji w drzewie prefiksowym", "spadek wydajności dla dużych i rzadkich baz"], correct: [2], explain: "Kompresja w drzewie prefiksowym to cecha FP-Growth; pozostałe punkty to ograniczenia Apriori.", src: "W08, slajd 30", note: "W08-reguly-asocjacyjne" },
  { id: "W08-37", w: "W08", c: "apriori-vs-fp", type: "single", q: "Analityk ma dużą, rzadką bazę i niski min_support. Który wybór jest zgodny z wykładem?", options: ["Apriori, bo generuje kandydatów poziomami", "FP-Growth, bo unika jawnych kandydatów", "Apriori, bo wymaga mniej przebiegów po bazie", "Oba, bo przy niskim progu działają tak samo"], correct: [1], explain: "Apriori traci wydajność przy dużych, rzadkich bazach i niskim progu; FP-Growth kompresuje dane i unika jawnych kandydatów.", src: "W08, slajd 32", note: "W08-reguly-asocjacyjne" },
]});

// data/W09.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W09-01", w: "W09", c: "oltp-olap", type: "single", q: "Które operacje wykład przypisuje do OLTP?", options: ["SELECT i agregacje", "INSERT, UPDATE, DELETE", "roll-up i drill-down", "slice i dice"], correct: [1], explain: "OLTP obsługuje transakcje (INSERT, UPDATE, DELETE); OLAP to SELECT i agregacje.", src: "W09, slajd 4", note: "W09-hurtownie-danych" },
  { id: "W09-02", w: "W09", c: "oltp-olap", type: "single", q: "Który opis pasuje do OLAP / hurtowni danych, a nie do OLTP?", options: ["dane aktualne i szczegółowe", "model znormalizowany", "dane historyczne i zintegrowane", "użytkownicy: aplikacje, operatorzy"], correct: [2], explain: "OLAP: dane historyczne, zintegrowane, model często denormalizowany, użytkownicy to analitycy i BI.", src: "W09, slajd 4", note: "W09-hurtownie-danych" },
  { id: "W09-03", w: "W09", c: "oltp-olap", type: "single", q: "Pytanie „pokaż trend sprzedaży” jest według wykładu typowe dla:", options: ["OLAP / hurtowni danych", "systemu OLTP", "operacyjnej składnicy danych", "obszaru pośredniego"], correct: [0], explain: "OLTP to „dodaj zamówienie”, OLAP to „pokaż trend sprzedaży”.", src: "W09, slajd 4", note: "W09-hurtownie-danych" },
  { id: "W09-04", w: "W09", c: "wlasciwosci", type: "single", q: "Dane z wielu systemów są ujednolicane (identyfikatory, formaty dat, waluty, kody). Którą właściwość hurtowni opisano?", options: ["zorientowana tematycznie", "nieulotna", "zmienna w czasie", "zintegrowana"], correct: [3], explain: "Zintegrowana: dane z wielu systemów są ujednolicane.", src: "W09, slajd 6", note: "W09-hurtownie-danych" },
  { id: "W09-05", w: "W09", c: "wlasciwosci", type: "single", q: "Co oznacza, że hurtownia danych jest nieulotna?", options: ["Dane są organizowane wokół obszarów analizy", "Dane są głównie dopisywane, nie aktualizowane", "Dane z wielu systemów są ujednolicane", "Dane są przechowywane tylko w pamięci RAM"], correct: [1], explain: "Nieulotna: dane są głównie dopisywane, a nie stale aktualizowane jak w OLTP.", src: "W09, slajd 6", note: "W09-hurtownie-danych" },
  { id: "W09-06", w: "W09", c: "wlasciwosci", type: "single", q: "Która z poniższych NIE jest klasyczną właściwością hurtowni danych?", options: ["zmienna w czasie", "zorientowana tematycznie", "znormalizowana", "nieulotna"], correct: [2], explain: "Klasyczne właściwości: zorientowana tematycznie, zintegrowana, zmienna w czasie, nieulotna.", src: "W09, slajd 6", note: "W09-hurtownie-danych" },
  { id: "W09-07", w: "W09", c: "data-mart", type: "single", q: "Hurtownia danych z wybranego obszaru, skupiona na jednym dziale organizacji, to:", options: ["Data Lake", "Lakehouse", "ODS", "Data mart"], correct: [3], explain: "Data mart przechowuje dane z wybranego obszaru, np. sprzedaży.", src: "W09, slajd 8", note: "W09-hurtownie-danych" },
  { id: "W09-08", w: "W09", c: "data-mart", type: "single", q: "Dlaczego data mart ma większą wydajność niż hurtownia danych?", options: ["Bo ma mniejszy rozmiar danych", "Bo przechowuje dane surowe", "Bo jest w pełni znormalizowany", "Bo nie przechowuje historii"], correct: [0], explain: "Data mart: większa wydajność ze względu na mniejszy rozmiar danych.", src: "W09, slajd 8", note: "W09-hurtownie-danych" },
  { id: "W09-09", w: "W09", c: "platformy", type: "single", q: "Która platforma służy do przechowywania danych surowych, strukturalnych i niestrukturalnych (logi, pliki, IoT)?", options: ["Data Warehouse", "Data Lake", "Data Mart", "ODS"], correct: [1], explain: "Data Lake: przechowywanie danych surowych, strukturalnych i niestrukturalnych.", src: "W09, slajd 9", note: "W09-hurtownie-danych" },
  { id: "W09-10", w: "W09", c: "platformy", type: "single", q: "Do czego według wykładu służy ODS?", options: ["Do raportów sprzedaży za kilka lat", "Do przechowywania logów i danych IoT", "Do bieżącego raportowania operacyjnego", "Do analityki i ML na jednej platformie"], correct: [2], explain: "ODS: bieżące raportowanie operacyjne, dane aktualne lub krótkoterminowe.", src: "W09, slajd 9", note: "W09-hurtownie-danych" },
  { id: "W09-11", w: "W09", c: "platformy", type: "single", q: "Połączenie data lake i hurtowni, z analityką, ML i raportowaniem na jednej platformie, to:", options: ["Lakehouse", "Data Mart", "Data Warehouse", "Obszar pośredni"], correct: [0], explain: "Lakehouse łączy data lake i hurtownię; dane surowe i tabelaryczne.", src: "W09, slajd 9", note: "W09-hurtownie-danych" },
  { id: "W09-12", w: "W09", c: "hd-vs-bd", type: "single", q: "Która cecha dotyczy relacyjnej bazy danych, a nie hurtowni?", options: ["dane obejmują długi okres", "nadmiarowość danych", "operacje dopisywania danych", "operacje CRUD na danych"], correct: [3], explain: "Baza danych: dane zmienne, operacje CRUD; hurtownia: dopisywanie i nadmiarowość.", src: "W09, slajd 10", note: "W09-hurtownie-danych" },
  { id: "W09-26", w: "W09", c: "hd-vs-bd", type: "single", q: "Która cecha opisuje hurtownię danych, a nie relacyjną bazę danych?", options: ["dane zmienne", "dane historyczne", "dane znormalizowane", "dane z krótkiego okresu czasu"], correct: [1], explain: "Hurtownia ma dane historyczne z długiego okresu; baza danych ma dane zmienne, znormalizowane, z krótkiego okresu.", src: "W09, slajd 10", note: "W09-hurtownie-danych" },
  { id: "W09-27", w: "W09", c: "hd-vs-bd", type: "single", q: "Które zdanie o hurtowni danych jest zgodne ze slajdem porównującym ją z relacyjną bazą danych?", options: ["Nie korzysta z relacyjnych mechanizmów przechowywania", "Ma strukturę zoptymalizowaną pod bieżące operacje", "Często używa relacyjnych mechanizmów, ale ma inny cel", "Przechowuje dane znormalizowane, bez nadmiarowości"], correct: [2], explain: "Hurtownia często wykorzystuje relacyjne mechanizmy, ale jest projektowana pod inny cel niż system transakcyjny.", src: "W09, slajd 10", note: "W09-hurtownie-danych" },
  { id: "W09-13", w: "W09", c: "architektura", type: "single", q: "Jaką rolę pełni obszar pośredni w architekturze hurtowni?", options: ["Udostępnia GUI i wizualizację danych", "Optymalizuje zasilanie hurtowni", "Przechowuje dane jednego działu", "Ukrywa szczegóły techniczne danych"], correct: [1], explain: "Dodatkowa warstwa (obszar pośredni) optymalizuje działania związane z zasilaniem hurtowni.", src: "W09, slajd 13", note: "W09-hurtownie-danych" },
  { id: "W09-28", w: "W09", c: "architektura", type: "single", q: "Jakie warstwy tworzą podstawową architekturę systemu analitycznego?", options: ["źródło danych, hurtownia, analiza i wizualizacja", "źródło danych, obszar pośredni, data marts", "źródło, staging, transformacja, hurtownia, raport", "operacyjna składnica, hurtownia danych, data marts"], correct: [0], explain: "Podstawowa architektura ma trzy warstwy: źródło danych, hurtownia danych, analiza i wizualizacja.", src: "W09, slajd 12", note: "W09-hurtownie-danych" },
  { id: "W09-29", w: "W09", c: "architektura", type: "single", q: "W architekturze z operacyjną składnicą danych dane przechodzą kolejno przez:", options: ["źródła → obszar pośredni → operacyjna składnica → hurtownia", "źródła → hurtownia → operacyjna składnica → obszar pośredni", "źródła → operacyjna składnica → hurtownia → obszar pośredni", "źródła → operacyjna składnica → obszar pośredni → hurtownia"], correct: [3], explain: "Na schemacie: źródła danych → operacyjna składnica danych → obszar pośredni → hurtownia → wizualizacja i analiza.", src: "W09, slajd 14", note: "W09-hurtownie-danych" },
  { id: "W09-14", w: "W09", c: "podejscia", type: "single", q: "Które ryzyko wykład przypisuje podejściu bottom-up?", options: ["długi czas wdrożenia", "brak szybkich efektów", "ryzyko silosów", "wymaga dobrego governance"], correct: [2], explain: "Bottom-up: kolejne data marty, szybkie efekty, ale ryzyko silosów.", src: "W09, slajd 17", note: "W09-hurtownie-danych" },
  { id: "W09-15", w: "W09", c: "podejscia", type: "single", q: "Podejście „najpierw model całej organizacji” to:", options: ["Hybrydowe", "Bottom-up", "Data mart", "Top-down"], correct: [3], explain: "Top-down: spójność i centralna kontrola, ale długi czas wdrożenia.", src: "W09, slajd 17", note: "W09-hurtownie-danych" },
  { id: "W09-16", w: "W09", c: "jakosc", type: "single", q: "Który wskaźnik jakości odpowiada na pytanie „czy ten sam obiekt nie występuje wielokrotnie?”", options: ["Spójność", "Unikalność", "Kompletność", "Poprawność"], correct: [1], explain: "Unikalność dotyczy duplikatów; spójność dotyczy sprzeczności między tabelami.", src: "W09, slajd 20", note: "W09-hurtownie-danych" },
  { id: "W09-17", w: "W09", c: "jakosc", type: "single", q: "Wartość wieku klienta wynosi 250 lat. Który wskaźnik jakości danych jest naruszony?", options: ["Poprawność", "Aktualność", "Unikalność", "Kompletność"], correct: [0], explain: "Poprawność: czy wartości mieszczą się w dopuszczalnych zakresach.", src: "W09, slajd 20", note: "W09-hurtownie-danych" },
  { id: "W09-18", w: "W09", c: "semantyka-lineage", type: "single", q: "Co pokazuje lineage?", options: ["Właścicieli danych w organizacji", "Definicje miar i certyfikowane KPI", "Drogę danych od źródła do raportu", "Uprawnienia użytkowników do danych"], correct: [2], explain: "Lineage: źródło, staging, transformacja, hurtownia, raport.", src: "W09, slajd 22", note: "W09-hurtownie-danych" },
  { id: "W09-19", w: "W09", c: "semantyka-lineage", type: "single", q: "Warstwa, która ukrywa techniczne szczegóły danych i udostępnia użytkownikom pojęcia biznesowe, to:", options: ["obszar pośredni", "warstwa semantyczna", "operacyjna składnica", "tabela faktów"], correct: [1], explain: "Warstwa semantyczna zawiera m.in. definicje miar, nazwy biznesowe pól, hierarchie i KPI.", src: "W09, slajd 21", note: "W09-hurtownie-danych" },
  { id: "W09-20", w: "W09", c: "governance", type: "single", q: "Dział sprzedaży i finansów mają różne definicje „przychodu”, a raporty są niespójne. Czego brakuje?", options: ["denormalizacji wymiarów", "operacyjnej składnicy danych", "pseudonimizacji danych", "data governance (ładu danych)"], correct: [3], explain: "Przykład z wykładu: bez governance raporty będą niespójne.", src: "W09, slajd 23", note: "W09-hurtownie-danych" },
  { id: "W09-30", w: "W09", c: "governance", type: "single", q: "Zasady zarządzania danymi w organizacji, obejmujące m.in. właścicieli danych i retencję danych, to:", options: ["lineage", "warstwa semantyczna", "data governance", "metadane"], correct: [2], explain: "Data governance (ład danych) to zasady zarządzania danymi w organizacji.", src: "W09, slajd 23", note: "W09-hurtownie-danych" },
  { id: "W09-31", w: "W09", c: "governance", type: "single", q: "Który element NIE należy do zakresu data governance według wykładu?", options: ["retencja danych", "reguły agregacji", "właściciele danych", "kontrola jakości danych"], correct: [1], explain: "Reguły agregacji należą do warstwy semantycznej; governance obejmuje m.in. właścicieli, jakość i retencję danych.", src: "W09, slajd 23", note: "W09-hurtownie-danych" },
  { id: "W09-21", w: "W09", c: "granularnosc", type: "single", q: "Hurtownia przechowuje tylko sprzedaż miesięczną. Co wynika z tego według wykładu?", options: ["Nie odpowie na pytanie o sprzedaż dzienną", "Nie policzy sprzedaży rocznej regionu", "Nie można użyć schematu gwiazdy", "Nie można wykonać operacji roll-up"], correct: [0], explain: "Granularność decyduje, na jakie pytania można odpowiedzieć.", src: "W09, slajd 26", note: "W09-hurtownie-danych" },
  { id: "W09-32", w: "W09", c: "granularnosc", type: "single", q: "Co według wykładu decyduje o tym, na jakie pytania będzie można odpowiedzieć w hurtowni danych?", options: ["granularność danych", "nieulotność danych", "warstwa semantyczna", "lineage danych"], correct: [0], explain: "Granularność, czyli poziom szczegółowości, decyduje, na jakie pytania można odpowiedzieć w hurtowni.", src: "W09, slajd 26", note: "W09-hurtownie-danych" },
  { id: "W09-33", w: "W09", c: "granularnosc", type: "single", q: "Który z przykładów granularności podanych na wykładzie jest najmniej szczegółowy?", options: ["całe zamówienie", "sprzedaż dzienna produktu", "sprzedaż miesięczna kategorii", "sprzedaż roczna regionu"], correct: [3], explain: "Przykłady idą od pojedynczej pozycji zamówienia do sprzedaży rocznej regionu, która łączy najwięcej zdarzeń.", src: "W09, slajd 26", note: "W09-hurtownie-danych" },
  { id: "W09-22", w: "W09", c: "fakt-miara-wymiar", type: "single", q: "Kwota sprzedaży w tabeli faktów to według wykładu:", options: ["fakt", "wymiar", "miara", "klucz sztuczny"], correct: [2], explain: "Miara to wartość liczbowa przypisana do faktu, np. kwota sprzedaży.", src: "W09, slajd 27", note: "W09-hurtownie-danych" },
  { id: "W09-23", w: "W09", c: "fakt-miara-wymiar", type: "single", q: "Czym jest wymiar?", options: ["Zdarzeniem, które analizujemy", "Kontekstem analizy", "Wartością liczbową faktu", "Poziomem szczegółowości"], correct: [1], explain: "Wymiar to kontekst analizy: czas, produkt, klient, lokalizacja, kanał.", src: "W09, slajd 27", note: "W09-hurtownie-danych" },
  { id: "W09-24", w: "W09", c: "olap-operacje", type: "single", q: "Analityk przechodzi z widoku rocznego na kwartały, a potem na miesiące. Jaka to operacja OLAP?", options: ["operacja roll-up", "operacja slice", "operacja dice", "operacja drill-down"], correct: [3], explain: "Drill-down: zejście do większej szczegółowości (rok, kwartał, miesiąc).", src: "W09, slajd 34", note: "W09-hurtownie-danych" },
  { id: "W09-25", w: "W09", c: "olap-operacje", type: "single", q: "Wybór podzbioru po kilku wymiarach (rok 2025, region wschodni, kategoria laptopy) to:", options: ["dice", "slice", "roll-up", "drill-down"], correct: [0], explain: "Slice to jeden przekrój; dice to podzbiór po kilku wymiarach.", src: "W09, slajd 34", note: "W09-hurtownie-danych" },
]});

// data/W10.js
(window.QUIZ_DATA ||= []).push({ subject: "data", questions: [
  { id: "W10-01", w: "W10", c: "oltp-problemy", type: "single", q: "Który z poniższych NIE jest problemem analizy na bazie modelu OLTP wymienionym na wykładzie?", options: ["Duża liczba złączeń znormalizowanych tabel", "Brak pełnej historii przez nadpisywanie wartości", "Zbyt mała liczba znormalizowanych tabel", "Niespójne definicje klienta lub produktu"], correct: [2], explain: "Problemem jest właśnie rozproszenie danych w wielu znormalizowanych tabelach, a nie ich mała liczba.", src: "W10, slajd 2", note: "W10-modele-danych" },
  { id: "W10-26", w: "W10", c: "oltp-problemy", type: "single", q: "Długie zapytania analityczne uruchamiane w systemie OLTP spowalniają obsługę bieżących transakcji. Który problem z wykładu to opisuje?", options: ["Brak pełnej historii zmian", "Niespójne definicje klienta i produktu", "Duża liczba złączeń tabel", "Obciążenie systemu operacyjnego"], correct: [3], explain: "Długie zapytania analityczne obciążają system operacyjny OLTP i spowalniają obsługę transakcji.", src: "W10, slajd 2", note: "W10-modele-danych" },
  { id: "W10-02", w: "W10", c: "elementy-modelu", type: "single", q: "Element modelu wymiarowego opisujący kontekst zdarzenia, np. czas, produkt, klienta i lokalizację, to:", options: ["tabela faktów", "miara obliczeniowa", "hierarchia wymiaru", "tabela wymiaru"], correct: [3], explain: "Tabele wymiarów opisują kontekst zdarzenia; tabela faktów przechowuje zdarzenia i wartości liczbowe.", src: "W10, slajd 3", note: "W10-modele-danych" },
  { id: "W10-03", w: "W10", c: "elementy-modelu", type: "single", q: "Na jakie pytanie odpowiadają miary w modelu wymiarowym?", options: ["Ile?", "Kto?", "Gdzie?", "Kiedy?"], correct: [0], explain: "Wymiary odpowiadają na pytania kto, co, gdzie, kiedy i w jaki sposób; miary na pytanie ile.", src: "W10, slajd 13", note: "W10-modele-danych" },
  { id: "W10-04", w: "W10", c: "kroki-projektu", type: "single", q: "Który krok projektowania modelu wymiarowego następuje bezpośrednio po wyborze procesu biznesowego?", options: ["Wybór wymiarów", "Określenie ziarna", "Wybór miar", "Wybór typu SCD"], correct: [1], explain: "Kolejność: wybór procesu, określenie ziarna, wybór wymiarów, wybór miar.", src: "W10, slajd 5", note: "W10-modele-danych" },
  { id: "W10-27", w: "W10", c: "kroki-projektu", type: "single", q: "Która kolejność kroków projektowania modelu wymiarowego jest zgodna z wykładem?", options: ["proces → ziarno → wymiary → miary", "proces → wymiary → miary → ziarno", "ziarno → proces → wymiary → miary", "proces → miary → ziarno → wymiary"], correct: [0], explain: "Najpierw wybór procesu biznesowego, potem ziarno, a dopiero po nim wymiary i miary.", src: "W10, slajd 5", note: "W10-modele-danych" },
  { id: "W10-28", w: "W10", c: "kroki-projektu", type: "single", q: "Krok projektowania, w którym określa się, jakie zdarzenie lub działanie organizacji będzie analizowane, to:", options: ["Wybór wymiarów analizy", "Określenie ziarna tabeli faktów", "Wybór procesu biznesowego", "Wybór miar liczbowych"], correct: [2], explain: "Krok 1 to wybór procesu biznesowego, np. sprzedaży produktów.", src: "W10, slajd 5", note: "W10-modele-danych" },
  { id: "W10-05", w: "W10", c: "proces-obiekt", type: "single", q: "Który z poniższych jest obiektem biznesowym, a nie procesem biznesowym?", options: ["realizacja zamówienia", "obsługa reklamacji", "dostawca", "wykonanie płatności"], correct: [2], explain: "Obiekt biznesowy to osoba, rzecz, miejsce lub pojęcie; dostawca jest obiektem, pozostałe to procesy.", src: "W10, slajd 7", note: "W10-modele-danych" },
  { id: "W10-29", w: "W10", c: "proces-obiekt", type: "single", q: "Powtarzalne działanie lub zdarzenie, które ma być mierzone i analizowane, to według wykładu:", options: ["proces biznesowy", "obiekt biznesowy", "ziarno tabeli faktów", "miara addytywna"], correct: [0], explain: "Tak zdefiniowano proces biznesowy. Obiekt biznesowy to osoba, rzecz, miejsce lub pojęcie.", src: "W10, slajd 7", note: "W10-modele-danych" },
  { id: "W10-30", w: "W10", c: "proces-obiekt", type: "single", q: "Klient, produkt i sklep to obiekty biznesowe. Przez co są one zwykle reprezentowane w modelu wymiarowym?", options: ["przez tabelę faktów", "przez miary bazowe", "przez klucze naturalne", "przez tabele wymiarów"], correct: [3], explain: "Proces jest zwykle reprezentowany przez tabelę faktów, a obiekty biznesowe przez tabele wymiarów.", src: "W10, slajd 8", note: "W10-modele-danych" },
  { id: "W10-06", w: "W10", c: "ziarno", type: "single", q: "Co określa ziarno (grain) tabeli faktów?", options: ["Liczbę wymiarów połączonych z faktami", "Poziom normalizacji tabel wymiarów", "Sposób agregacji miar w kostce OLAP", "Co reprezentuje jeden wiersz tabeli faktów"], correct: [3], explain: "Ziarno określa dokładnie, co reprezentuje jeden wiersz tabeli faktów.", src: "W10, slajd 9", note: "W10-modele-danych" },
  { id: "W10-07", w: "W10", c: "ziarno", type: "single", q: "Jakie ziarno podano na wykładzie dla przykładu „Magazyn”?", options: ["stan jednego produktu na koniec dnia", "jedna pozycja produktu na paragonie", "jedno zamówienie dostawcy", "miesięczna sprzedaż kategorii"], correct: [0], explain: "Magazyn: jeden wiersz to stan jednego produktu na koniec dnia.", src: "W10, slajd 9", note: "W10-modele-danych" },
  { id: "W10-08", w: "W10", c: "agregacja", type: "single", q: "Która zasada dotycząca ziarna padła na wykładzie?", options: ["Dane szczegółowe można odtworzyć z agregatów", "Agregować można później, szczegółów nie da się odzyskać", "Silna agregacja daje najwyższą elastyczność analiz", "Ziarno ustala się po wyborze miar"], correct: [1], explain: "Dane można agregować później, ale nie można odzyskać utraconego poziomu szczegółowości.", src: "W10, slajd 10", note: "W10-modele-danych" },
  { id: "W10-09", w: "W10", c: "agregacja", type: "single", q: "Większa agregacja danych w tabeli faktów oznacza:", options: ["więcej rekordów i wolniejsze raporty", "więcej możliwych analiz", "mniej możliwych analiz", "mniejszą liczbę wymiarów"], correct: [2], explain: "Większa agregacja: mniej rekordów, szybsze raportowanie, mniej możliwych analiz.", src: "W10, slajd 10", note: "W10-modele-danych" },
  { id: "W10-10", w: "W10", c: "mieszanie-ziaren", type: "single", q: "W tabeli faktów jeden rekord opisuje pozycję na paragonie, a inny całe zamówienie. Jaki skutek wskazano na wykładzie?", options: ["Utrata historii zmian w wymiarach", "Podwójne liczenie tych samych danych", "Większa redundancja tabel wymiarów", "Brak kluczy zastępczych w faktach"], correct: [1], explain: "Mieszanie ziaren daje błędne agregacje, podwójne liczenie i niejednoznaczne miary. Zasada: jedna tabela faktów = jedno ziarno.", src: "W10, slajd 11", note: "W10-modele-danych" },
  { id: "W10-31", w: "W10", c: "mieszanie-ziaren", type: "single", q: "Który z poniższych NIE jest skutkiem mieszania różnych ziaren w jednej tabeli faktów?", options: ["Błędne agregacje i raporty", "Podwójne liczenie tych samych danych", "Utrata historii zmian w wymiarach", "Niejednoznaczna interpretacja miar"], correct: [2], explain: "Utrata historii wynika z nadpisywania wartości w wymiarach, a nie z mieszania ziaren.", src: "W10, slajd 11", note: "W10-modele-danych" },
  { id: "W10-32", w: "W10", c: "mieszanie-ziaren", type: "single", q: "Którą zasadę dotyczącą tabel faktów sformułowano na wykładzie?", options: ["Jedna tabela faktów = jeden wymiar", "Jedna tabela faktów = jedna miara", "Jeden wymiar = jedna tabela faktów", "Jedna tabela faktów = jedno ziarno"], correct: [3], explain: "Każdy rekord tabeli faktów ma mieć to samo ziarno. Mieszanie ziaren daje błędne agregacje.", src: "W10, slajd 11", note: "W10-modele-danych" },
  { id: "W10-11", w: "W10", c: "addytywnosc", type: "single", q: "Miary, które można sumować tylko w wybranych wymiarach, ale nie we wszystkich, to miary:", options: ["addytywne", "obliczeniowe", "nieaddytywne", "póładdytywne"], correct: [3], explain: "Póładdytywne sumuje się w części wymiarów, np. stan magazynu po produktach, ale nie po czasie.", src: "W10, slajd 17", note: "W10-modele-danych" },
  { id: "W10-12", w: "W10", c: "addytywnosc", type: "single", q: "Saldo konta bankowego to według wykładu miara:", options: ["póładdytywna", "addytywna", "nieaddytywna", "bazowa bez wymiarów"], correct: [0], explain: "Saldo nie sumuje się po czasie, ale można je sumować po klientach i oddziałach.", src: "W10, slajd 17", note: "W10-modele-danych" },
  { id: "W10-13", w: "W10", c: "addytywnosc", type: "single", q: "Która miara jest nieaddytywna i analizuje się ją średnią ważoną?", options: ["Rabat kwotowy", "Stan magazynu", "Marża procentowa", "Koszt sprzedaży"], correct: [2], explain: "Marża procentowa jest nieaddytywna; analizuje się ją średnią ważoną.", src: "W10, slajd 18", note: "W10-modele-danych" },
  { id: "W10-14", w: "W10", c: "bazowe-obliczeniowe", type: "single", q: "Która z miar jest według wykładu miarą obliczeniową, a nie bazową?", options: ["wartość sprzedaży", "udział sprzedaży (%)", "liczba sprzedanych sztuk", "rabat kwotowy"], correct: [1], explain: "Miary obliczeniowe wylicza się z bazowych: średnia wartość zamówienia, marża procentowa, cena jednostkowa, udział sprzedaży.", src: "W10, slajd 20", note: "W10-modele-danych" },
  { id: "W10-33", w: "W10", c: "bazowe-obliczeniowe", type: "single", q: "Miary przechowywane bezpośrednio w tabeli faktów, np. koszt i rabat kwotowy, to miary:", options: ["bazowe", "obliczeniowe", "póładdytywne", "nieaddytywne"], correct: [0], explain: "Miary bazowe są przechowywane w tabeli faktów; obliczeniowe wylicza się na ich podstawie.", src: "W10, slajd 20", note: "W10-modele-danych" },
  { id: "W10-34", w: "W10", c: "bazowe-obliczeniowe", type: "single", q: "W tabeli faktów zapisano tylko marżę procentową, bez kosztu i wartości sprzedaży. Jaki to błąd według wykładu?", options: ["Mieszanie różnych ziaren w faktach", "Brak ważnego wymiaru analizy", "Wskaźniki zamiast danych bazowych", "Niewłaściwa agregacja miar"], correct: [2], explain: "Marża procentowa to wskaźnik wyliczany z miar bazowych. Przechowywanie wskaźników zamiast danych bazowych to częsty błąd.", src: "W10, slajd 21", note: "W10-modele-danych" },
  { id: "W10-15", w: "W10", c: "typ-faktow", type: "single", q: "Każdy rekord przedstawia stan systemu w określonym momencie, np. saldo konta na koniec miesiąca. To tabela faktów typu:", options: ["Transakcyjna", "Accumulating Snapshot", "Factless Fact Table", "Periodic Snapshot"], correct: [3], explain: "Periodic Snapshot zapisuje stan cyklicznie i często zawiera miary póładdytywne.", src: "W10, slajd 23", note: "W10-modele-danych" },
  { id: "W10-16", w: "W10", c: "typ-faktow", type: "single", q: "Rekord zamówienia przechowuje datę złożenia, wysyłki i dostawy i jest aktualizowany na kolejnych etapach. To:", options: ["Accumulating Snapshot", "Periodic Snapshot", "Transakcyjna tabela faktów", "Junk Dimension"], correct: [0], explain: "Accumulating Snapshot: jeden rekord na cały proces, wielokrotnie aktualizowany, daty etapów.", src: "W10, slajd 24", note: "W10-modele-danych" },
  { id: "W10-17", w: "W10", c: "typ-faktow", type: "single", q: "Rejestrujemy obecność studenta na zajęciach (data, student, przedmiot, sala) bez wartości liczbowych. Jak się analizuje taką tabelę?", options: ["Sumuje się miary addytywne", "Liczy się średnią ważoną miar", "Zlicza się rekordy", "Porównuje się kolejne migawki stanu"], correct: [2], explain: "Factless Fact Table nie ma miar; analiza polega na zliczaniu rekordów.", src: "W10, slajd 25", note: "W10-modele-danych" },
  { id: "W10-18", w: "W10", c: "wymiar-tabela", type: "single", q: "Która cecha NIE dotyczy tabeli wymiaru według wykładu?", options: ["zawiera klucz główny", "przechowuje miary biznesowe", "przechowuje atrybuty opisowe", "umożliwia filtrowanie i grupowanie"], correct: [1], explain: "Tabela wymiaru nie przechowuje miar; miary w wymiarach to jeden z najczęstszych błędów.", src: "W10, slajd 27", note: "W10-modele-danych" },
  { id: "W10-35", w: "W10", c: "wymiar-tabela", type: "single", q: "Która kolumna pasuje do tabeli wymiaru DimProduct z wykładu?", options: ["Marka", "Ilość", "Rabat", "Koszt"], correct: [0], explain: "Wymiar przechowuje atrybuty opisowe, np. markę i kategorię. Ilość, rabat i koszt to miary tabeli faktów.", src: "W10, slajd 27", note: "W10-modele-danych" },
  { id: "W10-36", w: "W10", c: "wymiar-tabela", type: "single", q: "Do tabeli DimProduct dodano kolumnę z wartością sprzedaży. Jaki skutek takiego błędu podano na wykładzie?", options: ["Utrata historii lub nadmiar danych", "Niezgodność z modelem wymiarowym", "Spadek wydajności raportów", "Problemy z integracją systemów"], correct: [1], explain: "Wartość sprzedaży to miara. Przechowywanie miar w tabelach wymiarów daje niezgodność z modelem wymiarowym.", src: "W10, slajd 45", note: "W10-modele-danych" },
  { id: "W10-19", w: "W10", c: "hierarchie", type: "single", q: "Przejście w hierarchii z poziomu „Miesiąc” do poziomu „Kwartał” (agregacja do wyższego poziomu) to:", options: ["drill-down", "normalizacja", "role-playing", "roll-up"], correct: [3], explain: "Roll-up agreguje do wyższego poziomu; drill-down przechodzi do szczegółów.", src: "W10, slajd 29", note: "W10-modele-danych" },
  { id: "W10-37", w: "W10", c: "hierarchie", type: "single", q: "Analityk ogląda sprzedaż za kwartał i chce zobaczyć ją w podziale na poszczególne miesiące. To operacja:", options: ["roll-up", "role-playing", "normalizacja", "drill-down"], correct: [3], explain: "Drill-down to przejście do szczegółów, tu z kwartału do miesięcy. Roll-up działa odwrotnie.", src: "W10, slajd 29", note: "W10-modele-danych" },
  { id: "W10-38", w: "W10", c: "hierarchie", type: "single", q: "Co według wykładu określa hierarchia w wymiarze?", options: ["Co reprezentuje jeden wiersz faktów", "Kolejne poziomy szczegółowości", "Sposób obsługi zmian w wymiarach", "Klucze łączące fakty z wymiarami"], correct: [1], explain: "Hierarchia określa kolejne poziomy szczegółowości danych, np. Dzień -> Miesiąc -> Kwartał -> Rok.", src: "W10, slajd 29", note: "W10-modele-danych" },
  { id: "W10-20", w: "W10", c: "klucz-zastepczy", type: "single", q: "Czym charakteryzuje się klucz zastępczy (Surrogate Key)?", options: ["Pochodzi z systemu źródłowego", "Ma znaczenie biznesowe, np. P-1032", "Tworzony w hurtowni, bez znaczenia biznesowego", "Może się zmieniać wraz z kodem produktu"], correct: [2], explain: "Klucz zastępczy tworzy hurtownia; jest stały i nie niesie znaczenia biznesowego.", src: "W10, slajd 31", note: "W10-modele-danych" },
  { id: "W10-21", w: "W10", c: "klucz-zastepczy", type: "single", q: "Jakie klucze według wykładu przechowuje się w tabelach faktów?", options: ["Klucze zastępcze", "Klucze naturalne", "Kody z systemów źródłowych", "Klucze główne faktów zamiast obcych"], correct: [0], explain: "W tabelach faktów przechowywane są klucze zastępcze, a nie klucze naturalne.", src: "W10, slajd 31", note: "W10-modele-danych" },
  { id: "W10-22", w: "W10", c: "specjalne-wymiary", type: "single", q: "Jeden wymiar daty pełni role daty zamówienia i daty dostawy. To przykład:", options: ["Degenerate Dimension", "Junk Dimension", "Role-Playing Dimension", "Conformed Dimension"], correct: [2], explain: "Role-Playing: jeden wymiar w różnych rolach. Degenerate to np. numer faktury w tabeli faktów.", src: "W10, slajd 34", note: "W10-modele-danych" },
  { id: "W10-39", w: "W10", c: "specjalne-wymiary", type: "single", q: "Ten sam wymiar produktu wykorzystują tabela faktów sprzedaży i tabela faktów stanów magazynu. To przykład:", options: ["Conformed Dimension", "Junk Dimension", "Role-Playing Dimension", "Degenerate Dimension"], correct: [0], explain: "Conformed Dimension (wymiar zgodny) to wspólny wymiar wykorzystywany przez wiele tabel faktów.", src: "W10, slajd 38", note: "W10-modele-danych" },
  { id: "W10-40", w: "W10", c: "specjalne-wymiary", type: "single", q: "Który z poniższych NIE jest szczególnym rodzajem wymiaru wymienionym na wykładzie?", options: ["Degenerate Dimension", "Periodic Snapshot", "Junk Dimension", "Conformed Dimension"], correct: [1], explain: "Periodic Snapshot to typ tabeli faktów, a nie szczególny rodzaj wymiaru.", src: "W10, slajd 34", note: "W10-modele-danych" },
  { id: "W10-23", w: "W10", c: "gwiazda-platek", type: "single", q: "Który opis pasuje do schematu płatka śniegu w porównaniu ze schematem gwiazdy?", options: ["Wymiary denormalizowane i mniej JOIN", "Wymiary znormalizowane i niższa wydajność", "Większa redundancja i mniej tabel", "Najczęściej stosowany w hurtowniach i BI"], correct: [1], explain: "Płatek śniegu powstaje przez normalizację wymiarów: mniej redundancji, więcej JOIN, niższa wydajność.", src: "W10, slajd 37", note: "W10-modele-danych" },
  { id: "W10-41", w: "W10", c: "gwiazda-platek", type: "single", q: "Dlaczego według wykładu większość hurtowni danych wykorzystuje schemat gwiazdy?", options: ["Ma najmniejszą redundancję danych w wymiarach", "Najłatwiej w nim aktualizować tabele wymiarów", "Najlepszy kompromis prostoty i wydajności", "Zapewnia największą spójność danych"], correct: [2], explain: "Gwiazda daje najlepszy kompromis między prostotą a wydajnością. Mniejsza redundancja i łatwa aktualizacja to zalety płatka śniegu.", src: "W10, slajd 37", note: "W10-modele-danych" },
  { id: "W10-42", w: "W10", c: "gwiazda-platek", type: "single", q: "Która cecha NIE jest zaletą schematu płatka śniegu według wykładu?", options: ["mniej powielanych danych", "łatwiejsza aktualizacja wymiarów", "większa spójność danych", "wyższa wydajność zapytań"], correct: [3], explain: "Płatek śniegu ma niższą wydajność zapytań przez więcej JOIN. Wyższa wydajność to cecha gwiazdy.", src: "W10, slajd 36", note: "W10-modele-danych" },
  { id: "W10-24", w: "W10", c: "scd", type: "single", q: "Firma chce poprawnych raportów historycznych po zmianie kategorii produktu. Który typ SCD zalecono?", options: ["SCD Type 2", "SCD Type 1", "SCD Type 3", "Nadpisanie wartości w faktach"], correct: [0], explain: "Type 2 tworzy nowy rekord z nowym kluczem zastępczym i zachowuje pełną historię.", src: "W10, slajd 44", note: "W10-modele-danych" },
  { id: "W10-25", w: "W10", c: "scd", type: "single", q: "Jak SCD Type 3 obsługuje zmianę wartości w wymiarze?", options: ["Nadpisuje starą wartość nową wartością", "Dodaje nowy rekord z nowym kluczem", "Usuwa rekord i wstawia nową wersję", "Dodaje kolumnę z poprzednią wartością"], correct: [3], explain: "Type 3 trzyma aktualną i poprzednią wartość w jednym rekordzie: historia częściowa.", src: "W10, slajd 41", note: "W10-modele-danych" },
]});

